programs.sol:
"""Predict small formatting, Unicode-fragment, and grammatical effects.

Most tokens stay near zero. Carriage returns after other text and closing
reasoning/tool-call tags are positive; long indentation and some grammatical
forms are negative. Unicode fragments are distinguished by whether they
finish a character or leave one incomplete. This is only a partial predictor:
it does not reproduce the component's scattered word-specific responses.
"""
import unicodedata

READS = ()
REFLEXIVES = frozenset('''myself yourself himself herself itself ourselves
                         yourselves themselves'''.split())
WEEKDAYS = frozenset('''monday tuesday wednesday thursday friday saturday
                       sunday'''.split())


def value(prefix, seen_other):
    text = prefix.token_strings[-1]
    word = text.strip().lower()
    if text == '\r':
        return 0.138 if seen_other else -0.089
    if text in ('</think>', '</tool_call>'):
        return 0.073
    if text == '<think>':
        return -0.058
    if text == '<tool_call>':
        return -0.039
    if text in ('<|im_end|>', '</tool_response>'):
        return -0.027
    if text == '<|im_start|>':
        return 0.010
    if word in REFLEXIVES:
        return -0.037
    if word in WEEKDAYS:
        return -0.028
    if word == 'being':
        return -0.062
    if word == 'been':
        return -0.029
    if text.isspace():
        spaces, tabs = text.count(' '), text.count('\t')
        if '\n' not in text:
            if text.startswith('\t') and spaces >= 15:
                return max(-0.10, -0.005 * (spaces - 7))
            if tabs >= 5:
                return -0.025
            if set(text) == {' '} and 22 <= spaces <= 64:
                return -0.030
        return -0.004 if text == '\n\n' else 0.001
    if '\ufffd' in text:
        now = prefix.text_prefixes[-1]
        before = prefix.text_prefixes[-2] if prefix.position else ''
        completed = now.rstrip('\ufffd')[len(before.rstrip('\ufffd')):]
        if now.endswith('\ufffd'):
            return 0.020 if completed else 0.044
        names = ' '.join(unicodedata.name(c, '') for c in completed)
        if 'HIRAGANA' in names or 'KATAKANA' in names:
            return 0.041
        return 0.005
    if not text.isascii() and word.isalpha():
        if text.startswith(' '):
            return 0.014
        names = ' '.join(unicodedata.name(c, '') for c in word)
        if any(script in names for script in ('HIRAGANA', 'KATAKANA', 'HANGUL')):
            return 0.011
        return 0.007 if 'CYRILLIC' in names else 0.004
    return 0.002


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    seen_other = carry[1] if carry is not None and carry[0] == doc else False
    prediction = value(prefix, seen_other)
    return (doc, seen_other or prefix.token_strings[-1] != '\r'), float(prediction)

"""A sparse lexical detector of prominence, people, and important figures.

The listed prominence adjectives and person/role words receive negative
activations.  Importance modifiers amplify figures, points and characters;
"very important" and "statistically significant" are weaker.  Chinese person
terms and Japanese/Chinese 氏 are strong.  This is a spelling-sensitive
approximation, not a rule that treats every synonym alike.  It omits the
component's many small, unrelated lexical responses.  English rules use
space-prefixed tokens and damp capitalized forms.  A small common
function-word lexicon supplies weaker signed background offsets.  Importance
words at document starts receive a separate, stronger negative estimate.
"""
READS = ()

PROMINENCE = {'notable': -0.62, 'influential': -0.57, 'prominent': -0.46}
LEXICON = {
    'important': -0.13, 'significant': -0.17, 'famous': -0.18,
    'figures': -0.45, 'figure': -0.24, 'points': -0.10,
    'leaders': -0.46, 'leader': -0.28, 'officials': -0.24,
    'personnel': -0.19, 'presidents': -0.49, 'celebrities': -0.31,
    'players': -0.11, 'characters': -0.06,
}
# Weak background responses of common quantifiers, auxiliaries and prepositions.
FUNCTION_WORDS = {
    'other': 0.057, 'some': 0.046, 'any': 0.039, 'certain': 0.12,
    'many': 0.035, 'few': 0.046, 'every': 0.052, 'only': 0.035,
    'both': -0.048, 'more': -0.029, 'less': -0.061, 'most': 0.028,
    'have': -0.032, 'has': -0.018, 'will': -0.029,
    'who': -0.051, 'where': -0.035, 'your': -0.029,
    'under': 0.062, 'upon': -0.097, 'within': -0.058,
    'through': -0.041, 'above': -0.059,
    'back': -0.055, 'out': -0.036, 'ever': -0.12,
}
EAST_ASIAN_TERMS = {
    '人物': -1.45, '的人物': -0.88, '人士': -0.89, '名人': -0.80,
    '人员': -0.57, '人員': -0.50, '氏': -0.57,
    '领袖': -0.62, '領袖': -0.62, '领导': -0.33, '領導': -0.33,
    '负责人': -0.52, '成员': -0.39, '代表': -0.27,
    '专家': -0.26, '專家': -0.26,
    '著名': -0.41, '知名': -0.31, '重要': -0.31, '要点': -0.46,
}
IMPORTANCE_MODIFIERS = {
    'key', 'main', 'important', 'significant', 'major', 'principal',
    'leading', 'notable', 'prominent', 'influential',
}
SOCIAL_MODIFIERS = {'public', 'historical', 'religious', 'political', 'military'}
AMPLIFIED_NOUNS = {'figure', 'figures', 'points', 'players', 'characters'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    new_document = carry is None or carry[0] != doc
    previous = '' if new_document else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    value = EAST_ASIAN_TERMS.get(word, 0.0)
    if token.startswith(' '):
        value = PROMINENCE.get(lower, LEXICON.get(lower, 0.0))
        if word == lower:
            value += FUNCTION_WORDS.get(word, 0.0)
        if word != lower:
            value *= 0.7
            if lower == 'figure':
                value = -0.05
        if lower in AMPLIFIED_NOUNS:
            if previous in IMPORTANCE_MODIFIERS:
                value -= 0.60
            elif (previous in SOCIAL_MODIFIERS
                  and lower in {'figure', 'figures'}):
                value -= 0.35
            if previous == 'key' and lower == 'figures':
                value -= 0.35
        if lower == 'important' and previous == 'very':
            value = 0.02
        if lower == 'significant' and previous == 'statistically':
            value = -0.06
        if new_document and lower in {'key', 'important', 'significant'}:
            value = -0.75
    if word == 'able' and previous == 'not':
        value = -0.6  # Tokenized as Not + able.
    if word in {'人员', '人員'} and previous in {'领导', '領導', '骨干', '军事'}:
        value -= 0.7
    if word == '人物':
        if previous in {'代表', '关键', '的关键', '關鍵'}:
            value -= 0.7
        elif previous in {'历史', '的历史', '政治', '的政治'}:
            value -= 0.25
    return (doc, lower), float(value)

programs.luna:
"""Approximate rare responses to words describing prominent people and things."""
