NOTABLE_TERMS = {
    "notable", "prominent", "influential", "leader", "leaders",
    "人物", "人士", "人員", "人员", "领导", "領導", "名人", "要点",
    "组成部分", "氏",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    return None, -0.7 if word in NOTABLE_TERMS else 0.0

"""A sparse lexical sketch of the rare high-impact cases: formal Chinese
administrative terms tend negative, proof terms positive. Most tokens get 0.
"""

READS = ()

ADMIN_TERMS = {
    "巡视", "增值税", "统一", "从严治", "严肃", "全国", "名额", "统",
}
PROOF_TERMS = {"证明", "村党支部"}

# Rare code-context examples in the harvest, not part of the Chinese pattern.
CODE_TERMS_NEGATIVE = {"stdlib"}
CODE_TERMS_POSITIVE = {".Annotations"}


def step(carry, prefix, upstream):
    """Give the listed surface words their usual sign; abstain elsewhere."""
    word = prefix.token_strings[-1].strip()
    if word in PROOF_TERMS or word in CODE_TERMS_POSITIVE:
        return None, 0.7
    if word in ADMIN_TERMS or word in CODE_TERMS_NEGATIVE:
        return None, -0.7
    return None, 0.0

programs.sol:
"""A vertical-bar detector that adapts when bars repeat.

Isolated bars give a large negative activation; dense tables and nearby
bar pairs give smaller ones. Logical operators, quoted bars and line-end
bars are weaker. Unicode vertical strokes, TeX bar names and absolute-
value words also get negative predictions. Unrelated tokens get zero.
"""
import math
import re

READS = ()
DECAY = math.exp(-1.0 / 50.0)
VERTICAL_STROKES = {"│", "丨", "∣", "‖"}
JOINED_BARS = ("|^", "|-", '"|', "'|", '|"', "|'", "_|", "|>")


def bar_shape(s):
    """Strength, nearby-bar adjustment, its distance scale, density penalty."""
    if "||" in s:
        return 1.36, 0.46, 12.0, 0.07
    if "|=" in s:
        return 2.24, 1.93, 12.0, 0.07
    if "\n" in s or "\r" in s:
        return 3.0, -0.9, 6.0, 0.4
    if any(x in s for x in ("|.", "|$", "|/")):
        return 2.0, 2.4, 3.0, 0.2
    if any(x in s for x in JOINED_BARS):
        return 3.42, 1.06, 12.0, 0.07
    if s.strip() == "|":
        return 4.63, 1.98 if s == "|" else 1.54, 12.0, 0.07
    return 4.44, 0.93, 12.0, 0.07


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent, age, position, tail = 0.0, 10000, 0, ""
    else:
        recent, age, position, tail = carry[1:]
        recent *= DECAY
        age += 1
        position += 1

    s = prefix.token_strings[-1]
    word = s.strip()
    value = 0.0
    if "|" in s and not (s.startswith("<|") and s.endswith("|>")):
        strength, adjustment, scale, penalty = bar_shape(s)
        operator = "||" in s or "|=" in s
        # Short documents have a slightly stronger isolated-bar response.
        ordinary = strength > 4.0
        if ordinary and position == 0:
            strength = 4.0 if s == "|" else 4.3
        elif ordinary:
            strength += 0.52 * math.exp(-position / 100.0)
        value = -strength + adjustment * math.exp(-age / scale)
        # A horizontal-rule run is another repetitive table delimiter.
        if s == "|" and tail.endswith("---"):
            value += 1.25
        value /= 1.0 + penalty * recent
        recent += 0.3 if operator else 1.0
        if not operator:
            age = 0
    elif word in VERTICAL_STROKES:
        value = -1.8 if word in {"│", "丨"} else -1.0
    elif word in {"Vert", "vert", "mid"}:
        command = re.search(r"\\([lr]?)$", tail)
        if command and not s[:1].isspace():
            side = command.group(1)
            if word == "mid":
                value = -2.2
            elif word == "Vert":
                value = {"l": -3.4, "r": -2.0, "": -2.7}[side]
            else:
                value = {"l": -4.7, "r": -3.0, "": -3.7}[side]
        else:
            # These spellings also fire when they are fragments of words.
            value = -0.5 if s[:1].isspace() else -1.1
    elif word.lower().strip("._-(") in {"abs", "absolute"}:
        value = -0.5

    return (doc, recent, age, position, (tail + s)[-16:]), float(value)

programs.haiku:
"""Vertical-bar detector: a layer-0 MLP feature that is strongly negative on the "|" character.

Almost everywhere the component is silent (about 0). It turns on for vertical-bar
characters, which carry most of its variance:
  - a bare bar, " |" or "|", gives about -3.8;
  - a bar glued to a bracket, quote or backslash ("(|", "}|", ' "|', "|\\") gives about -4.5;
  - a bar that ends a line ("|\\n") gives about -2;
  - other bar combinations ("||", "|=") give about -1.3.
Chat-template markers such as <|im_start|> contain bars but do not fire, so they are
excluded. Nothing else is predicted: the sign is always negative.
"""

READS = ()

GLUED = ("(|", "|\\", "}|", ")|", ' "|', "|string")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token.startswith("<|") or token.endswith("|>"):
        return carry, 0.0
    bare = token.strip(" ")
    if bare == "|":
        return carry, -3.8
    if bare in ("|\n", "|\n\n"):
        return carry, -2.0
    if token in GLUED:
        return carry, -4.5
    if "|" in token:
        return carry, -1.3
    return carry, 0.0

