"""A lexical sketch of recurring positive cues: English focus/stance and
frequency words, paired quantifiers, and a form of be after there. It also
marks a few Chinese modifiers/particles and the English-looking -ly ending;
all other tokens get zero. These cues predict a typical positive pulse.
"""
READS = ()

FOCUS_AND_STANCE = {
    "only", "actually", "exactly", "simply", "specifically", "chiefly",
    "maybe", "probably", "perhaps",
}
TIME_AND_FREQUENCY = {"now", "always", "originally", "also"}
PAIRED_QUANTIFIERS = {"both", "either"}
COPULAS = {"is", "are", "were", "be"}
CHINESE_MODIFIERS = {
    "只", "几乎", "幾乎", "也不", "就", "都是", "既然", "具体", "正式", "累计",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    previous = ""
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2].strip().lower().rstrip(".,;:!?")
    if word in FOCUS_AND_STANCE:
        value = 0.85
    elif word in TIME_AND_FREQUENCY:
        value = 0.75
    elif word in PAIRED_QUANTIFIERS:
        value = 0.70
    elif word in COPULAS and previous == "there":
        value = 0.85
    elif word == "without":
        value = 0.90
    elif word in CHINESE_MODIFIERS:
        value = 0.65
    elif word.endswith("ly"):
        value = 0.28
    else:
        value = 0.0
    return None, 1.04 * value

programs.sol:
"""Closing boundaries of short quoted, bracketed, or formatted spans.

Most tokens are quiet. A standalone closing quote is strong after a word;
parentheses and formatting marks are weaker. Long spans and repeated
nearby delimiters weaken the response. Opening quotes, word-internal
apostrophes, and marks fused with commas/newlines are mostly quiet. The
state remembers recent delimiters and nested parentheses, resetting at
each document boundary; ordinary tokens return zero.
"""
import math

READS = ()
QUOTE_PAIRS = {'”': '“', '’': '‘', '」': '「', '』': '『',
               '》': '《', '»': '«', '〉': '〈', '“': '„'}
TRACKED = set('()（）\"\'`*$') | set(QUOTE_PAIRS.values())


def step(carry, prefix, upstream):
    s, doc, p = (prefix.token_strings[-1], prefix.document_ids[-1],
                 prefix.position)
    if carry is None or carry[0] != doc:
        previous, last, history, stack = '', {}, {}, []
    else:
        _, previous, last, history, stack = carry
    end = previous[-1:]
    word_end = end.isalpha() or end.isdigit() or end == '�'

    def strength(mark, height, decay=18, repetition=0.15):
        distance = p - last.get(mark, (-1000, ''))[0]
        count = sum(p-i < 128 for i in history.get(mark, ()))
        return (height * math.exp(-max(distance-3, 0)/decay)
                / math.sqrt(1 + repetition*count))

    value = 0.0
    if s == '<|endoftext|>':
        value = 1.57
    elif s in QUOTE_PAIRS:
        value = (strength(QUOTE_PAIRS[s], 2.85, repetition=0.10)
                 if word_end else 0.05)
    elif s in {'\"', "'", '`', '\\"', "\\'"}:
        quote = s[-1]
        mark = quote
        alternate = '‘' if quote == "'" else '„' if quote == '\"' else quote
        if last.get(alternate, (-1000, ''))[0] > last.get(quote, (-1000, ''))[0]:
            mark = alternate
        before = last.get(mark, (0, ''))[1]
        if not word_end:
            value = (strength(mark, 0.8)
                     if quote == '`' and end and not end.isspace() else -0.08)
        elif quote == "'" and mark == quote and before.isalpha():
            value = -0.10
        elif (previous.strip()[:1] in '(=' and
              previous.strip().lstrip('(=') in {'f', 'b', 'r'}):
            value = -0.10  # A Python string prefix, not a closing quote.
        else:
            height = 0.65 if before in {'=', '(', '['} else 2.75
            if end.isdigit():
                height *= 0.65
            if quote == '`':
                height = 1.0 if before == '`' else 2.2
            value = strength(mark, height, repetition=0.03 if quote == '`' else 0.15)
        if len(s) == 2:  # An escaped quote is a weaker boundary.
            value *= 0.40
    elif s.strip(' ') in {')', '）'}:
        opener = '(' if ')' in s else '（'
        if stack:
            opened, before = stack[-1]
            d = p-opened
            height = 0.95 if before.isalpha() else 1.32
            count = sum(p-i < 128 for i in history.get(opener, ()))
            value = height * math.exp(-max(d-3, 0)/30) / math.sqrt(1+0.15*count)
            if previous.strip().isupper() and len(previous.strip()) > 1:
                value += 0.35
        else:
            value = 0.10 if opener in last else 0.60
        if s.startswith(' '):
            value = 0.58
    elif s == ']':
        value = 0.26
    elif s.strip(' ') == '}':
        value = 0.63 if word_end else 0.13
    elif s.strip(' ') == '__':
        value = 0.40 if s.startswith(' ') else 0.90
    elif s in {'*', '**', '$'}:
        before = last.get(s, (0, ''))[1]
        height = 0.9 if s == '$' else 1.5
        if s != '$' and before.isalnum():
            height = 0.4 if s == '**' else 0.0
        value = strength(s, height, 9 if s == '$' else 13, 0) if word_end else -0.05
    elif s and len(s) > 1 and all(c in ')]}\"\'' for c in s):
        value = 0.50
    elif (s.endswith('`') and s.strip('`')
          and all(c in "\"'()[]{}>`" for c in s)):
        value = strength('`', 0.95, repetition=0)
    elif s == '>':
        value = 0.25

    if '**' in s:
        i = s.index('**')
        last['**'] = (p, s[i-1] if i else end)
    for i, char in enumerate(s):
        before = s[i-1] if i else end
        if char in '(（':
            stack.append((p, before))
        elif char in ')）' and stack:
            stack.pop()
        if char in TRACKED:
            last[char] = (p, before)
            history[char] = [j for j in history.get(char, []) if p-j < 128] + [p]
    return (doc, s, last, history, stack), float(value)

programs.haiku:
"""Closing-delimiter detector for layers.0.mlp.down_proj:2889.

The component fires on tokens that close a span: a closing quotation mark or backtick,
a closing parenthesis, the end-of-text marker, and a few other closers. Its activation is
set mostly by which token it is, so the program is a small table of closing tokens with a
typical activation for each. Opening marks (such as '("' or ' "') and ordinary text predict 0.
"""

READS = ()

END_OF_TEXT = "<|endoftext|>"
QUOTE_CLOSERS = {'"': 1.5, "”": 2.0, "`": 1.5, '"`': 2.0, "»": 1.4, "」": 1.2, "』": 1.4, "》": 2.5}
PAREN_CLOSERS = {")": 0.9, "）": 0.85, " )": 0.6, "))": 0.5, "')": 0.5, '")': 0.3, ")}": 0.6, ")$": 0.4}
OTHER_CLOSERS = {"'": 0.5, "__": 0.9, "**": 0.5, "}": 0.5, "}}": 0.6, "$": 0.5, ">": 0.3, "]": 0.2}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == END_OF_TEXT:
        return carry, 1.6
    for table in (QUOTE_CLOSERS, PAREN_CLOSERS, OTHER_CLOSERS):
        if token in table:
            return carry, table[token]
    return carry, 0.0

programs.luna:
"""Predict a small baseline and pulses at text-closing marks."""
import unicodedata

READS = ()

END = "<|endoftext|>"
BASELINE = 0.011
PULSE = 0.33
BRACKET_PULSES = {
    ")": 0.95, "]": 0.42, "}": 0.58,
    "」": 2.3, "』": 1.5, "】": 1.2, "〉": 1.2, "》": 1.2,
}
PAIRS = {"“": "”", "‘": "’", "«": "»", "‹": "›"}
CLOSERS = {close: open_ for open_, close in PAIRS.items()}
QUOTE_STRENGTH = {
    '"': 1.05, "'": 1.5, "`": 2.0,
    "“": 2.3, "‘": 2.3, "«": 2.3, "‹": 2.3,
}


def closing_quote(token, state):
    """Pair quote marks and backticks, ignoring apostrophes inside words."""
    pulse = 0.0
    for i, char in enumerate(token):
        if char in ('"', "'", "`"):
            before = token[i - 1] if i else " "
            after = token[i + 1] if i + 1 < len(token) else " "
            if before.isalnum() and after.isalnum():
                continue
            state[char] = not state[char]
            if state[char]:
                continue
            score_char = char
        elif char in PAIRS:
            state[char] = True
            continue
        elif char in CLOSERS:
            opener = CLOSERS[char]
            if not state[opener]:
                continue
            state[opener] = False
            score_char = opener
        else:
            continue
        pulse = max(pulse, QUOTE_STRENGTH[score_char])
    return pulse


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        state = {'"': False, "'": False, "`": False}
        state.update({open_: False for open_ in PAIRS})
    else:
        state = dict(carry[1])

    token = prefix.token_strings[-1]
    value = 1.55 if token == END else closing_quote(token, state)
    stripped = token.rstrip()
    if stripped and token != END:
        mark = stripped[-1]
        value = max(value, BRACKET_PULSES.get(mark, 0.0))
        if unicodedata.category(mark) == "Pe":
            value = max(value, 0.6)

    return (doc, state), float(BASELINE + PULSE * value)

"""Give a modest positive estimate to the standalone article words that recur in examples."""
READS = ()

ARTICLE_ACTIVATION = {"a": 0.30, "an": 0.51, "the": 0.30, "one": 0.17}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    return None, float(ARTICLE_ACTIVATION.get(word, 0.0))

programs.haiku:
"""Sleep, rest, dreams and waiting detector for one MLP component (layer 0, down_proj unit 2892).

The component reads the current token and answers with a negative number when it is a word
about sleep, rest or waiting. It is a lookup on the current token only, in several languages:
  - "sleep" and its forms (sleeping, asleep, insomnia, and 睡 / ngủ): about -8, the strongest;
