    'bei': 1.82, 'beim': 1.48, 'aus': 1.07, 'auf': 0.99,
    'mit': 0.71, 'zu': 0.57, 'durch': 0.79,
    'nach': 0.55, 'vor': 0.56, 'seit': 1.01,
    'zum': 0.47, 'zur': 0.46, 'über': 0.37,
    'das': 0.61, 'die': 0.15,
    'nicht': 0.65, 'auch': 0.70, 'mehr': 0.93,
    'wieder': 0.88, 'selbst': 0.86, 'etwas': 0.80,
    'ihr': 0.85, 'ihre': 1.03, 'unser': 0.99,
    'wie': -1.10,
}

