    word = token.strip()
    lower = word.lower()
    spaced = token.startswith(' ')
    if lower == 'one':
        if word == 'One':
            return 0.98
        if not spaced:
            return 0.10 if previous and previous[-1].isalpha() else 0.91
        restriction = previous.strip().lower()
        if restriction == 'no':
            return 0.43
        if restriction in ('only', 'least', 'than'):
            return 0.67
        if restriction == 'exactly':
            return 0.55
        return 0.93
    if lower in ('either', 'neither') and spaced:
        return 1.03
