            return 4.85 if spaced else 4.05
        return ARTICLES[lower]
    if lower in DETERMINER_ROOTS:
        return DETERMINER_ROOTS[lower]
    for root in DETERMINER_ROOTS:
        if lower.startswith(root) and lower[len(root):] in INFLECTIONS:
            return INFLECTIONS[lower[len(root):]]
