        if spaced and len(lower) == 4:
            return 3.3
        return 2.1 if lower == 'einzel' else 0.7
    if spaced and lower in GERMAN_GRAMMAR:
        return GERMAN_GRAMMAR[lower]
    if any(m in lower for m in EI_MORPHEMES):
        return 1.05 if len(word) <= 6 else 0.4
    if 'ei' in lower and word.isalpha():
        length = len(word)
