ARTICLE_FORMS = {"eine", "einen", "einer", "eines", "einem", "einige", "einzel"}
EI_WORDS = {
    "sein", "seine", "seinen", "seinem", "seiner", "kein", "keine", "keinen",
    "mein", "meine", "meinen", "dein", "deine", "bei", "beim", "rein", "klein",
    "frei", "weit", "zeit", "stein", "heim", "reich", "weiss", "weiß", "eig", "eigen",
}
ONE_WORDS = {
    "one", "either", "neither", "een", "egy", "один", "един", "一つ", "zwei",
    "etwas", "nichts", "jemand",
}
PREPOSITIONS = {
    "auf", "aus", "mit", "zu", "nach", "vor", "durch", "seit", "über", "nicht",
    "auch", "wieder", "mehr", "dabei", "ihr", "ihre", "ihren", "unser", "selbst",
    "zum", "zur", "bei",
}
ENGLISH_EI = {
    "their", "being", "receive", "received", "receiving", "receiver", "weight",
    "weights", "height", "heights", "foreign", "protein", "proteins", "neighbor",
    "neighbour", "neighborhood", "reign", "seeing", "ceiling", "eight", "vein",
    "perceive", "perceived", "weigh", "weighted", "heir", "seize", "seizure",
}
