    "grateful", "thankful", "thanks", "thank you", "good", "great",
    "perfect", "sorry", "responsible", "known", "better", "best",
)

PURPOSE_WORDS = (
    "test", "tests", "tested", "testing", "method", "methods", "solve",
    "check", "checking", "formula", "criteria", "criterion", "technique",
    "tool", "evidence", "standard", "standards", "procedure", "protocol",
    "instructions", "function", "program", "equation", "model", "process",
)


def _ends_with_word(text, words):
    return any(text == word or text.endswith(" " + word) for word in words)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        history = ""
