    "substantial": 1.3, "numerous": 1.1, "countless": 1.3, "notable": 1.1,
    "noteworthy": 1.1, "undoubtedly": 1.8, "undeniable": 1.6, "arguably": 1.2,
    "questionable": 1.4, "dubious": 1.5, "comparable": 0.9, "somewhat": 0.8,
    "quite": 0.6, "decent": 0.8, "modest": 0.8,
