"""Layer-0 MLP down_proj component 2899: a "data / information / system" word detector.

What it does: it writes a positive value into the residual stream on the token itself
(no context needed), chiefly:
  * the end-of-text token <|endoftext|> (the strongest, about 1.15), which marks the
    boundary between packed documents;
  * the word "data" (and its translations and code forms) about 0.9;
  * "information", "system", "control", and "because", about 0.65;
  * a looser group of computing and media nouns (display, image, video, memory, ...)
    about 0.25.
Every other token predicts 0.

Why: the activation is almost entirely a function of the current token, so a short
list of concepts, grouped by meaning, captures most of its variance.
"""

READS = ()

END_OF_TEXT = {"<|endoftext|>"}
DATA_WORDS = {"data", "_data", ".data", "/data", "数据", "データ", "datos", "dados"}
CORE_WORDS = {
    "information", "info", "情報", "informações", "información",
    "system", "systems", "系统", "系統", "システム", "систем",
    "control", "controls", "controlled", "控制",
    "because", "porque", "因为",
}
LOOSE_WORDS = {
    "display", "displays", "displayed", "displaying", "image", "video", "audio", "text",
    "record", "recorded", "recording", "memory", "metadata", "database", "signal", "message",
    "messages", "graphics", "instruction", "instructions", "register", "computer",
}
LEVELS = ((END_OF_TEXT, 1.15), (DATA_WORDS, 0.9), (CORE_WORDS, 0.65), (LOOSE_WORDS, 0.25))


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    for words, level in LEVELS:
        if word in words:
            return carry, level
    return carry, 0.0

"""layers.0.mlp.down_proj:2901 -- a "quantifier right after a preposition" detector.

The component fires on English quantifier and demonstrative words (each, all, any, both,
this, these, some, many, ...) when the word directly follows a preposition, as in
"in all caps", "of each", "for any", "on this". The same words after a comma, semicolon,
"and" or "or" get nothing, and so do prepositions and other words.

Prediction: a strong tier (each, every, all, any, both, either) gets a high value after a
preposition and a small one otherwise. A weaker tier (this, these, some, many, ...) gets a
medium value after a preposition and a small one otherwise. After a comma, semicolon,
"and" or "or", the value is 0. The numbers are group means fitted on training text.
It misses "that" and "one" after prepositions, and the per-word variation within each tier.
"""

PREPOSITIONS = {
    "in", "of", "for", "to", "on", "at", "with", "by", "from", "into", "about",
    "under", "over", "across", "through", "within", "among", "per", "during",
    "between", "against", "via",
}
STRONG = {"each", "every", "all", "any", "both", "either"}
WEAK = {
    "this", "these", "those", "some", "many", "several", "most", "such", "various",
    "different", "other", "another", "same", "one", "two", "more", "no", "anything",
    "everything", "everyone", "anyone", "multiple",
}
BREAKS = {",", ";", "and", "or"}
READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if len(prefix.token_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        before = ""
    else:
        before = prefix.token_strings[-2].strip().lower()
    after_prep = before in PREPOSITIONS
    if before in BREAKS:
        return carry, 0.0
    if word in STRONG:
        return carry, 4.0 if after_prep else 0.9
    if word in WEAK:
        return carry, 1.7 if after_prep else 0.3
    return carry, 0.0

