"""Approximate the strong negative 'then' and positive tab-onset responses.

Capitalization and 'and'/'since' change the strength of 'then'. The small
lexicon covers sequencing words in other languages. A single tab is strongest
after a newline, weaker after numbers, and nearly silent after another tab
token. Longer tab runs have a weaker positive response. Ignore the many small
responses to other tokens.
"""
READS = ()

# Translations of 'then', 'next', or 'after that'.
SEQUENCING_WORDS = {
    'dann': -0.74,
    'luego': -0.50,
    'alors': -0.70,
    'entonces': -0.88,
    'então': -0.96,
    '然后': -0.70,
    '然後': -0.60,
    'тогда': -0.51,
    'затем': -0.42,
    'puis': -0.30,
    'ensuite': -0.26,
    'その後': -0.38,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    word = token.strip().lstrip('_')
    value = 0.0
    if word.lower() == 'then':
        value = -1.24 if token.startswith(' ') else -1.16
        if not word.islower():
            value = -1.04
        elif token.startswith('_'):
            value = -1.39
        elif previous.strip().lower() == 'and':
            value += 0.13
        elif previous.strip().lower() == 'since':
            value += 0.55
    elif word.lower() in SEQUENCING_WORDS:
        value = SEQUENCING_WORDS[word.lower()]
        if word.istitle():
            value *= 0.6
    elif token and set(token) == {'\t'}:
        if len(token) > 1:
            value = 0.74 if len(token) <= 5 else 0.62
            if first:
                value = 0.35
            elif previous.strip().isdigit():
                value -= 0.10
        elif first or previous.endswith('\t'):
            value = 0.05
        elif previous.endswith('\n'):
            value = 1.02
        elif previous.strip().isdigit():
            value = 0.81
        elif previous.isspace() and len(previous) > 2:
            value = 0.45
        else:
            value = 0.90
    elif token.isspace() and token.endswith('\t'):
        value = 0.48
    return (doc, token), value

