programs.sol:
"""A spelling-level quantity detector.

Many/more/few words, multiplicity prefixes, and translations give negative
signals. The standalone characters 多 and 少 are especially strong; compounds
are weaker. The detector fires on their spelling even inside names or code.
The preceding word modifies 'more', 'most', 'least', and quantity-noun
complements with 'of'. Most text predicts zero.
"""
READS = ()

# Each row is a familiar quantity/frequency word class and its typical strength.
WORD_CLASSES = (
    (-1.15, 'many mostly'),
    (-1.5, 'multiple plurality myriad'),
    (-1.8, 'fewer fewest'),
    (-0.95, 'numerous plethora handful'),
    (-0.75, 'rare rarely seldom scarce scant rarity plenty majority minority'),
    (-0.75, 'diverse diversity versatile versatility'),
    (-0.8, 'additional'),
    (-0.6, 'extra variety frequent lots'),
    (-0.3, 'several frequently additionally largely mainly'),
    (-1.0, 'countless abundant predominant predominantly plural'),
    (-0.17, 'multiply multiplied multiplying multiplication multiplier'),
    (-0.5, 'poly polym polys divers'),
    (-0.8, 'beaucoup plusieurs nombreux viele vielen muchos muchas muit'),
    (-0.8, 'множество несколько нескольких несколь çok birçok العديد'),
    (-1.5, 'mehr больше мног меньше أكثر'),
    (-1.0, 'wenig weniger menos мало немного'),
    (-2.5, 'много nhiều banyak 寡'),
    (-1.9, 'มาก thiểu đa たくさん'),
    (-0.6, 'più moins meer 더 많이 여러'),
    (-1.6, '丰富 丰富的 豐富 ほとんど'),
    (-0.85, '数量 大量 大量的 增加 额外'),
    (0.25, 'various enough everything'),
)
WORDS = {w: value for value, words in WORD_CLASSES for w in words.split()}


def quantity_value(token, previous):
    word = token.strip().lstrip('_-.').lower()
    if word in {'多', '少'}:
        return -7.7 if word == '多' else -5.85
    if word == '多少':
        return -2.5
    for phrase in ('很多', '许多', '許多', '好多', '众多', '这么多', '那么多'):
        if phrase in word:
            strength = 1.1 if phrase in {'许多', '許多'} else 2.2
            return -strength * len(phrase) / len(word)
    if '大多数' in word:
        return -1.3 if len(word) == 3 else -0.8
    if word == '差不多':
        return -0.9
    if '多' in word:
        if word in {'多了', '得多', '增多', '不多', '并不多'}:
            return -5.0
        if word.endswith('多'):
            return -4.3
        if word.startswith('更多'):
            return -3.5 if len(word) == 3 else -2.5
        if word in {'が多い', 'が多く', '多い', 'も多い', 'も多く',
                    '多样', '多元', '多彩', '多方'}:
            return -3.2
        return -2.1 if len(word) <= 3 else -1.4
    if '少' in word:
        if word == '少し':
            return -0.1
        if word in {'少女', '少年', '少爷'}:
            return -1.2
        if word in {'少ない', '少なく', '很少', '最少', '较少'}:
            return -3.2
        return -2.2 if len(word) <= 3 else -1.0
    if word == 'ít':
        return -2.8 if token[:1].isspace() else 0.0
    if word == '많':
        return -3.45
    if word == '다':
        return -2.6 if token[:1].isspace() else -1.15
    if word == 'of':
        if previous in {'number', 'plurality'}:
            return -0.28
        if previous in {'couple', 'pair', 'series', 'volume', 'ratio', 'thousands'}:
            return 0.35
        if previous in {'amount', 'quantity', 'percent', 'percentage',
                        'lot', 'list', 'collection', 'kind', 'sort'}:
            return 0.2
    if word == 'more':
        if token == ' more':
            if previous in {'is', 'are', 'was', 'were'}:
                return -1.1
            if previous in {'no', 'nothing', 'little', 'any', 'read'}:
                return -0.28
            if previous in {'a', 'much', 'one', 'bit', 'two', 'even'}:
                return -0.65
            return -0.88
        return -0.97
    if word == 'less':
        return -1.03 if token[:1].isspace() else -0.45
    if word == 'most':
        if token == 'most':
            return -0.3
        if previous == 'the':
            return -0.25
        return -0.13 if previous == 'at' else -0.8
    if word == 'least':
        return -0.29 if previous == 'at' else -0.8
    if word == 'few':
        return -1.3 if token.strip()[:1].isupper() else -0.76
    if word == 'multif':
        return -3.2
    if word in {'multi', 'multin', 'multid', 'multim', 'multit', 'multitude',
                'multicultural', 'multiline'}:
        return -2.3
    if word in {'mult', 'multip', 'multis', 'ulti', 'ultip', 'ultiple'}:
        return -1.55
    if word.startswith('multi') and word not in WORDS:
        return -1.0
    return WORDS.get(word, 0.0)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    value = quantity_value(token, previous)
    if '\ufffd' in token:
        # The current byte fragment may have just completed a quantity character.
        last = prefix.text_prefixes[-1][-1:]
        if last in {'多', '少'}:
            value = -8.8 if last == '多' else -5.8
    return (document, token.strip().lower()), float(value)

"""An ampersand detector, with weaker responses for technical syntax.

Single ampersands respond strongly; recent LaTeX math cues reduce their
response to about half. Logical AND, assignment and HTML escapes are
weaker still, except '&amp', which represents an ampersand itself.
Remember only 256 recent characters, resetting at document boundaries.
Non-ampersand tokens receive a small background value.
"""
import re

READS = ()
LATEX_MATH = re.compile(
    r'\\(?:begin|end|frac|sqrt|text|left|right|hline|pmatrix|'
    r'mathrm|mathbf|mathit|sum|sigma|alpha|beta|gamma|delta|'
    r'theta|vec|cr|cdot|nonumber|ldots|dots|pm|times|infty|'
    r'over|partial|lim|int|sin|cos|log)\b|\^\{|_\{'
)
HTML_ESCAPE = re.compile(r'&(?:lt|gt|quot|apos|nbsp|[a-z]+acute)')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    recent = '' if first else carry[1]
    s = prefix.token_strings[-1]

    if '＆' in s:
        value = 0.92
    elif '&' not in s:
        value = 0.0015
    elif '&&' in s:
        if '\n' in s:
            value = 0.06
        elif '(' in s or ')' in s:
            value = 0.20
        else:
            value = 0.25
    elif '&#' in s:
        value = 0.36
    elif '&amp' in s:
        value = 0.90
    elif HTML_ESCAPE.search(s):
        value = 0.28
    elif '&=' in s:
        value = 0.32
    elif '\n' in s:
        value = 0.72
    elif s.strip() == '&':
        if first:
            value = 0.75
        elif LATEX_MATH.search(recent):
            value = 0.66
        else:
            value = 1.15 if s.startswith(' ') else 1.06
    elif (
        len(s.split('&')[-1]) > 1
        or any(x in s for x in ("&'", '&_', '&['))
    ):
        value = 0.67
    else:
        value = 0.88

    return (doc, (recent + s)[-256:]), value

"""Detect the -ian family of adjective and noun endings.

Most suffix pieces get larger values than full nationality words.
Scientific eponyms can be especially strong; nationality, religious, and
political affiliation words also respond. A few related numerical/programming terms
are weaker triggers. Unrecognized tokens predict zero. The only state is the
current Latin-alphabet word, used to identify an eponym or occupation completed
by a suffix; it resets at document boundaries.
"""
import re

READS = ()

NATIONALITIES = frozenset('''
african albanian algerian american arab arabian argentine argentinian armenian
asian australian austrian belgian brazilian british bulgarian burmese canadian
catalan caucasian chilean chinese colombian croatian cuban czech danish dutch
egyptian english estonian ethiopian european finnish french georgian german
greek haitian hawaiian hebrew hungarian icelandic indian indonesian iranian
iraqi irish israeli italian jamaican japanese jewish jordanian kenyan korean
kurdish latvian lebanese lithuanian malaysian mexican moroccan nepali nigerian
norwegian pakistani palestinian persian peruvian filipino polish portuguese
roman romanian russian scottish serbian slovak slovenian somali soviet spanish
sudanese swedish swiss syrian taiwanese tamil thai tibetan tunisian turkish
ukrainian uruguayan venezuelan vietnamese welsh yugoslav yugoslavian zambian
