NATIONALITY_STRENGTH = {
    'asian': 3.0, 'indian': 2.7, 'english': 0.07, 'italian': 1.4,
    'russian': 1.65, 'roman': 0.55, 'norwegian': 1.0, 'german': 1.0,
    'greek': 1.0, 'pakistani': 2.0, 'egyptian': 1.2, 'hungarian': 1.2,
    'palestinian': 1.1, 'belgian': 1.3,
}
SCIENCE = {
    'abelian': 4.3, 'bayesian': 4.5, 'cartesian': 5.65, 'euclidean': 4.0,
    'gaussian': 4.9, 'hamiltonian': 5.9, 'hermitian': 5.9, 'jacobian': 5.0,
    'lagrangian': 6.0, 'newtonian': 6.8, 'riemannian': 4.65,
    'laplacian': 5.0, 'brownian': 5.3, 'eulerian': 6.3,
    'keynesian': 6.8, 'fuchsian': 5.9, 'markovian': 4.8,
}
AFFILIATIONS = {
    'christian': 2.6, 'christianity': 1.05, 'catholic': 1.3,
    'buddhist': 1.3, 'methodist': 1.3, 'muslim': 0.9, 'hindu': 0.9,
    'islamic': 0.75, 'republican': 1.3, 'democratic': 0.9,
    'socialist': 1.15, 'presbyterian': 1.6, 'lesbian': 1.7,
    'presidential': 1.0,
}
NUMERICAL_TERMS = {
    'mean': 0.4, 'means': 0.05, 'median': 1.8, 'radian': 0.4,
    'boolean': 1.1, 'bool': 0.3, 'nan': 0.4,
}
OCCUPATIONS = frozenset('''
politician musician physician technician electrician clinician mathematician
historian librarian comedian theologian optician pediatrician
'''.split())
NAMES = frozenset('''
adrian brian damian fabian ian julian marian sebastian vivian
'''.split())
STRONG_ENDINGS = frozenset('''
ian arian adian alian esian elian essian orian olian illian ilian anian onian
clidean aussian
'''.split())
MEDIUM_ENDINGS = frozenset('rian bian opian idian ussian lian'.split())
WEAK_ENDINGS = frozenset('ician itian odian wegian byterian itarian'.split())
ENDINGS = STRONG_ENDINGS | MEDIUM_ENDINGS | WEAK_ENDINGS


def response(token, previous_word):
    word = token.strip().lower().lstrip('-_.')
    singular = word[:-1] if word.endswith('s') and word != 'swiss' else word
    plural = singular != word
    if token == token.strip() and singular in ENDINGS:
        joined = (previous_word + singular).lower()
        value = SCIENCE.get(joined)
        if value is None:
            if joined in OCCUPATIONS and singular == 'ian':
                value = 2.0 if joined == 'mathematician' else 2.7
            elif token == 'Ian':
                value = 0.6
