    if token == token.strip():
        if singular in ('ean', 'ican', 'iana', 'iano', 'iani', 'orean'):
            return (2.8 if singular == 'orean' else 1.6) * (0.73 if plural else 1)
        if word in ('an', 'yan', 'uan'):
            return 0.22 if word == 'an' else 0.8
    if singular in SCIENCE:
        return SCIENCE[singular] * (0.73 if plural else 1.0)
    if singular in NATIONALITIES:
        default = (1.96 if singular.endswith(('ian', 'ican')) else
                   1.1 if singular.endswith(('ean', 'ese')) else
                   1.55 if singular.endswith('an') else
                   0.75 if singular.endswith('ish') else 0.45)
        return NATIONALITY_STRENGTH.get(singular, default) * (0.66 if plural else 1)
    if singular in AFFILIATIONS:
        factor = 0.52 if singular == 'christian' else 0.73
        return AFFILIATIONS[singular] * (factor if plural else 1.0)
    if word in NUMERICAL_TERMS or singular == 'radian':
        return NUMERICAL_TERMS.get(word, 0.4)
    if singular in OCCUPATIONS:
        return 0.25
    if singular in NAMES:
        return 0.5 if singular in ('ian', 'brian', 'sebastian') else 1.7
    if singular == 'victorian':
        return 3.2
    if singular == 'ovarian':
        return 0.6
    if singular.endswith('ian'):
        return 2.0 * (0.73 if plural else 1.0)
    if singular == 'alien':
