"""Approximate a mostly lexical container detector.

Literal container tokens get a large negative response. Storage vessels,
GUI/HTML enclosures, and Docker/Kubernetes get weaker negative responses;
selected Chinese container, vessel, capacity, and panel spellings are included.
Industry/value words, the division sign, and several accented letters are
secondary triggers. Unmatched tokens default to zero, omitting many weak
word-specific responses rather than storing a vocabulary-sized lookup table.

This is not a general semantic containment test: 'box' and the verb 'contain'
are not strong triggers. A one-token carry adds a small phrase continuation
response on ' of' and ' class', and resets at document boundaries.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    bare = token.strip()
    word = bare.lstrip('._-/<>([{').lower()
    if word == 'container':
        value = -5.1 if token == 'Container' else -4.45
    elif word == 'containers':
        value = -4.0
    elif bare == '容器':
        value = -3.65
    elif bare == '罐' or token == 'Panel':
        value = -1.5
    elif word in {'panel', 'jpanel', 'tank', 'linearlayout', 'parentnode'}:
        value = -1.25
    elif bare in {'瓶', '面板'}:
        value = -1.05
    elif bare == '容':
        value = -0.8
    elif word in {'panels', 'tanks', 'viewgroup'}:
        value = -0.8
    elif word == 'pane':
        value = -0.5
    elif word == 'div':
        if bare.startswith('<'):
            value = -1.5
        else:
            value = -1.3 if token == 'div' else -0.8
    elif bare == '÷':
        value = -1.5
    elif word == 'docker':
        value = -1.8
    elif word == 'ocker':
        value = -1.45
    elif word in {'kubernetes', 'ubernetes'}:
        value = -0.95
    elif word == 'wrapper':
        if bare.startswith('-'):
            value = -1.35
        else:
            value = -0.9 if token == bare else -0.75
    elif word in {'vessel', 'tray', 'holder', 'viewholder', 'condo'}:
        value = -0.55
    elif word in {'vessels', 'holders', 'bottle', 'bottles', 'bucket'}:
        value = -0.3
    elif word in {'contained', 'containing'}:
        if bare.startswith('-'):
            value = -0.75
        else:
            value = -0.23 if word == 'containing' else -0.06
    elif word in {'collection', 'collections', 'repository'}:
        value = -0.5 if bare[:1].isupper() else -0.27
    elif word == 'row':
        value = -0.35 if token == 'Row' else -0.12
    elif word == 'industry':
        value = -0.62 if bare.islower() else -0.45
    elif word == 'industries':
        value = -0.48 if bare.islower() else -0.12
    elif bare == '行业':
        value = -1.0
    elif word in {'valuable', 'invaluable'}:
        value = -0.85
    elif bare == 'ù':
        value = -1.3
    elif bare.lower() == 'ñ':
        value = -0.85
    elif bare in {'ò', 'ï', 'ð'}:
        value = -0.4
    else:
        value = 0.0

    # Continue the previous lexical response on 'of' or HTML 'class'.
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else 0.0
    context = 0.3 * previous if token in {' of', ' class'} else 0.0
    return (document, value), value + context

programs.luna:
"""Recognize words for containers, compartments, and interface panels.

The component is usually quiet, but has negative activations on a sparse set
of such nouns and markup terms. The especially strong container cases get a
larger prediction; this is a lexical sketch, not a contextual classifier.
"""

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()

    if "container" in word:
        return None, -4.3
    if "contained" in word:
        return None, -0.8
    if "panel" in word:
        return None, -1.1
    if word == "div":
        return None, -1.3
    if "docker" in word or word == "ocker":
        return None, -1.6
    if "wrapper" in word or word == "blockquote":
        return None, -0.8
    if word in {"pane", "vessel", "tank", "tanks", "row"}:
        return None, -0.7
    return None, 0.0

programs.haiku:
"""Layer-0 MLP down-projection component 2909: a "vague thing" word detector.

Reads only the current token (lowercased, spaces stripped) and returns a fixed value
per word class. The component is a negative detector for words meaning an unspecified
"thing", "stuff" or "something":
  * "thing" / "things" and 物 (Chinese/Japanese "thing"): about -5
  * "stuff" and the same idea in other languages (事, もの, こと, 东西, вещь, cosa,
    chose, ...): about -2
  * indefinite and question words ("what", "something", "nothing", "anything",
    "everything", "whatever"): about -1.4
  * "person", "people", 人, "item", "device", "substance", "phone" and their
    translations: about -1.1
  * "object", "gear", "equipment", "hardware", "physical" and similar: about -0.4
  * every other token: 0
Value depends only on the token, not on context.
"""

READS = ()

THING = {"thing", "things", "物"}
STUFF = {"stuff", "事", "もの", "こと", "東西", "东西", "вещ", "cosa", "cosas", "事物", "ること",
         "ものが", "ものを", "ことが", "ことを", "すること", "것", "việc", "şey", "chose", "choses", "物事", "事情"}
WHAT = {"what", "something", "nothing", "anything", "everything", "whatever"}
PEOPLE_ITEMS = {"person", "people", "persons", "人", "item", "items", "device", "devices",
                "substance", "substances", "phone", "phones", "persone", "personnes", "людей", "человек"}
GEAR = {"object", "objects", "gear", "equipment", "hardware", "physical", "drug", "phenomenon", "phenomena"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in THING:
        value = -5.0
    elif word in STUFF:
        value = -2.0
    elif word in WHAT:
        value = -1.4
    elif word in PEOPLE_ITEMS:
        value = -1.1
    elif word in GEAR:
        value = -0.4
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""English modifier-complement patterns, especially 'known/used for'.

'For' is positive after recognition, requirement, suitability and purpose
words. 'By' and 'to' after these words are usually negative. 'Given name'
is another strong positive phrase. The lexicon groups words by meaning;
the suffix -ed is a fallback for participles. An intervening -ly token
(or 'only', 'once', 'worldwide') preserves a weaker 'for' response. Other tokens are mostly assigned zero.
This explains the conspicuous phrase responses, not the small lexical
background across the rest of the vocabulary.
"""
READS = ()

LEXICON = {
    'recognition': 'known unknown',
    'requirement': 'required needed',
    'availability': 'available unavailable',
    'selection': (
        'recommended selected nominated proposed slated considered chosen '
        'desired preferred wanted planned assessed evaluated recognized taken'
    ),
    'request': 'asked requested demanded sought',
    'fitness': (
        'suitable suited eligible applicable acceptable appropriate '
        'inappropriate valid unfit important necessary essential vital crucial '
        'critical useful helpful beneficial valuable relevant sufficient '
        'accessible notable renowned'
    ),
    'purpose': 'used employed designed intended designated',
    'appraisal': (
        'good great better best perfect safe effective possible impossible '
        'challenging difficult ideal famous notorious grateful'
    ),
    'active': 'ask asks asking allow allows provide provides need use',
}
CLASS_OF = {
    word: meaning
    for meaning, words in LEXICON.items()
    for word in words.split()
}
IRREGULAR = set((
    'given shown seen found made written done mistaken meant built bought '
    'brought taught thought paid sent kept held read'
).split())

# Approximate activations: columns are 'for', 'by', 'to', 'in'.
COMPLEMENTS = {
    'ordinary': (.02, .05, 0., 0.),
    'recognition': (1.82, -.50, -.62, 0.),
    'requirement': (1.11, -.90, -.12, -.05),
    'availability': (.97, -.64, -.42, -.23),
    'selection': (1.19, -.32, -.11, .04),
    'request': (.75, -1.0, -.15, -.08),
    'fitness': (.76, -.29, -.10, .07),
    'purpose': (.77, -.34, 0., .09),
    'appraisal': (.43, -.14, -.07, .03),
    'active': (.33, -.02, .02, .04),
    'participle': (.46, -.13, -.04, -.02),
}


def word_class(word):
    fallback = 'participle' if word.endswith('ed') or word in IRREGULAR else 'ordinary'
    return CLASS_OF.get(word, fallback)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, earlier = '', ''
    if carry is not None and carry[0] == doc:
        previous, earlier = carry[1:]
    raw = prefix.token_strings[-1].strip()
    word = raw.lower()
    relation = word.lstrip('-_')  # Also recognize compound forms such as '-for'.
    meaning = word_class(previous)
    value = 0.0
    if relation in ('for', 'by', 'to', 'in'):
        column = ('for', 'by', 'to', 'in').index(relation)
        value = COMPLEMENTS[meaning][column]
        if meaning == 'ordinary' and raw == 'By':
            value = .18  # Capitalized attribution/byline marker.
        elif meaning == 'ordinary' and raw == 'For':
            value = -.015
        if relation == 'for' and (
            previous.endswith('ly') or previous in {'only', 'once', 'worldwide'}
        ):
            value = .16 + .35 * COMPLEMENTS[word_class(earlier)][0]
    elif word == 'name':
        value = .67 if previous == 'given' else .025
    elif meaning == 'recognition' and word == 'as':
        value = -.15
    return (doc, word, previous), float(value)

"""A small grammatical and formatting sketch of a weak, mixed signal.

Recognize common English grammatical forms and short constructions, with
case, line-break and document-initial adjustments. The small rules avoid a large
content-word lookup; most token-specific variation remains unexplained.
"""
READS = ()

# Shifts for recognizable grammatical classes.
FORMS = (
    (-0.017, 'be been being'),
    (0.015, 'are were'),
    (0.026, 'am'),
    (-0.019, 'them they'),
    (0.036, 'any anyone'),
    (0.028, 'few many several'),
    (-0.035, 'anything everything nothing something'),
    (0.016, 'which who'),
    (0.030, 'when why'),
    (-0.020, 'how'),
    (0.033, 'here there'),
)
FORM_RESPONSE = {w: v for v, words in FORMS for w in words.split()}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    initial = carry is None or carry[0] != doc
    previous = '' if initial else carry[1]
    token = prefix.token_strings[-1]
    s = token.strip()
    word = s.lower()
    value = -0.0017 + FORM_RESPONSE.get(word, 0.0)
    if initial:
        value -= 0.016
    if s == 'The':
        value += 0.020
    if s == 'In':
        value -= 0.022
    if '\n' in token:
        value += 0.006
    if '\n\n' in token:
        value -= 0.004
    if '\t' in token:
        value += 0.008
    if s == '!':
        value -= 0.024
    if word == 'is' and previous == 'what':
        value -= 0.092
    if word in {'a', 'an'} and previous in {'is', 'was', 'am'}:
        value += 0.021
    if word == 'the' and previous == 'of':
        value -= 0.018
    if word == 'the' and previous in {'have', 'has', 'had'}:
        value += 0.048
    if word == 'of' and previous in {'number', 'sum', 'list', 'combination'}:
        value -= 0.046
    if word == 'of' and previous in {'one', 'most', 'any', 'each'}:
        value += 0.044
    if word == 'to' and previous in {'want', 'going', 'according', 'due', 'order'}:
        value += 0.039
    if word == 'with' and previous in {'associated', 'called', 'connected', 'filled'}:
        value += 0.047
    return (doc, word), float(value)

programs.haiku:
"""Quantity-word detector for layers.0.mlp.down_proj component 2913.

The component is silent on almost all text. It turns negative on words that name a
number of things, and the more strongly the more "doubled" the meaning:
  - "double" (and "doubles", "doubled", Chinese "双") is strongest, about -5.5;
  - "two", "twice", "triple", "twin", "dual" and other "two" words (also in German,
    French, Spanish, Russian, Chinese) are about -1.8;
  - the other cardinal numbers "three" .. "twelve" (and their foreign forms) are about -1;
  - "one", "single", "couple", "multiple" are about -0.8, and "pair" about -0.6.
Digits ("2", "3") do not trigger it; the words do. Every other token predicts 0.
Each token is judged on its own text, so the prediction depends only on the current token.
"""

READS = ()

# Activation levels (typical values in the training data).
DOUBLE = {"double", "doubles", "doubled", "doubling", "双"}
TWO = {"two", "twice", "twin", "twins", "dual", "triple", "zwei", "dos", "deux",
       "два", "两个", "两种", "两者", "兩個"}
NUMBER = {"three", "four", "five", "six", "seven", "eight", "nine", "ten", "eleven",
          "twelve", "trois", "три", "zwe", "三", "四", "五", "六", "九"}
ONE = {"one", "single", "couple", "couples", "multiple"}
PAIR = {"pair", "pairs", "paired"}

LEVELS = [(DOUBLE, -5.5), (TWO, -1.8), (NUMBER, -1.0), (ONE, -0.8), (PAIR, -0.6)]


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower().lstrip("(")
    for words, value in LEVELS:
        if word in words:
            return None, value
    return None, 0.0

programs.sol:
"""A mostly spelling-driven negative response to 'id', not its meaning.

Isolated ID/Id, camel-case identifier endings, and short pieces ending in
'id' are strongest. Longer pieces, plurals, and familiar whole-word families
are weaker. Case and whitespace matter. Several short non-Latin spellings
are also recognized. The spelling 'acid' has its own especially strong
response. Everything else is zero; no context is retained. This summarizes
the large observed responses, not the small lexical and contextual residuals.
"""
READS = ()

# In these familiar word families, 'id' is not an isolated letter fragment.
WHOLE_WORD_FAMILIES = (
    'valid', 'void', 'avoid', 'grid', 'side', 'width', 'video', 'idea',
    'ident', 'provid', 'decid', 'consider', 'individ', 'david', 'android',
    'middle', 'guide', 'wide', 'hybrid', 'stupid', 'madrid',
)


def strength(token):
    word = token.strip()
    core = word.lstrip('._-/\'"([:')
    s = core.lower()
    bare = token == core
    if any(family in s for family in WHOLE_WORD_FAMILIES):
        return 0.08
    if s in {'said', 'paid', 'afraid'} or s.startswith('didn'):
        return 0.15
    if s in {'did', 'kids'}:
        return 1.3 if bare else 0.9
    if s in {'id', 'ids'}:
        if core.startswith('Id'):
            return 2.5 if bare else 2.0
        if bare:
            return 3.2 if s == 'ids' else (3.9 if core == 'ID' else 3.6)
        return (2.4 if core.startswith('id') else 2.8) if word == core else 2.6
    if core.endswith(('Id', 'ID', 'Ids', 'IDs')) and not core.isupper():
        value = max(0.9, 3.9 - 0.23 * (len(core) - 4))
        return value * (0.75 if s.startswith(('get', 'find', 'set')) else 1.0)
    if 'id' in s:
        plural = s.endswith('ids')
        stem = s[:-1] if plural else s
        n = len(stem)
        if stem.endswith('id'):
            if stem.endswith('oid'):
                value = 1.9 if n == 3 else 1.4
            elif stem.endswith('uid') and n > 3:
                value = 1.7
            elif n <= 3:
                value = 2.3 if stem in {'kid', 'wid'} else 3.6
            elif stem == 'acid':
                # This chemical word has an unusually strong spelling response.
                value = 5.0 if bare else 3.3
            elif n == 4:
                value = 2.5
            elif n <= 6:
                value = 2.3 if core.isupper() else 1.5
            else:
                value = 0.6
            return value * (0.75 if plural else 1.0)
        if s.startswith('bid') or s in {'aided', 'aiding'}:
            return 3.0
        if len(s) <= 5:
            return 1.5 if s.endswith('ida') else 0.75
        if s.startswith('mid') or s.endswith(('idge', 'idges')):
            return 0.9
        return 0.6 if s.endswith('iding') and len(s) <= 7 else 0.15
    if 'ид' in s:
        return 2.2 if s.endswith('ид') and len(s) <= 3 else 0.3
    return 1.4 if s in {'ید', 'يد', 'ิด'} else 0.0


def step(carry, prefix, upstream):
    return None, -float(strength(prefix.token_strings[-1]))

"""Separately tokenized accented letters and unfinished UTF-8 characters.

Common acute vowels are weak; circumflexes, ligatures, and accented capitals
are stronger. A preceding space usually raises the response. Strong pulses
are damped when the preceding 32 tokens already contain much non-ASCII text.
At a document start every response is halved, and the context is reset.
Two-character space-prefixed tokens with one non-ASCII Latin-1 letter get a
quarter-strength pulse.
Explicit rules cover a few other vowels, typographic signs, three control
characters, nonbreaking spaces, and a negative response to doubled middle dots.
It deliberately ignores most word-specific and fine contextual variation.
"""
import unicodedata as ud

READS = ()

# Token encodings of SPACE + a UTF-8 lead byte, before the letter is complete.
SPACED_LEADS = {
    1683: (0xC3, 2.8),
    9843: (0xC4, 2.6),
    25917: (0xC5, 2.9),
    1278: (0xD0, 0.7),
    8839: (0xD1, 0.3),
    86089: (0xE1, 0.65),
    2139: (0xC2, None),  # Its amplitude depends on recent text density.
}

SPECIAL_LATIN = {
    "æ": 1.45, "œ": 0.65, "ß": 0.6, "ſ": 0.25,
    "þ": 0.7, "ð": 1.45, "đ": 1.1, "ł": 0.25,
    "ı": 0.1, "İ": 0.2, "ẞ": 1.4,
}

SYMBOL_GROUPS = (
    ("§©®¶¿¡¼½¾ºª¸", 0.9),
    ("÷", 1.4),
    ("£±€™", 0.65),
    ("µ°", 0.3),
    ("¨¬", 0.5),
    ("«»", 0.2),
    ("•", 0.13),
    ("✓", 0.75),
)
SYMBOLS = {c: value for chars, value in SYMBOL_GROUPS for c in chars}
# Additional isolated vowel signs outside the Latin script.
OTHER_VOWELS = {"э": 0.55, "Э": 0.55, "إ": 0.9, "آ": 0.7, "โ": 1.0}


def latin_letter(c):
    """Accent type, base letter, and case describe the main positive pulses."""
    if c in SPECIAL_LATIN:
        return SPECIAL_LATIN[c]
    if c.lower() in SPECIAL_LATIN:
        return SPECIAL_LATIN[c.lower()] + 0.7
    name = ud.name(c, "")
    if "LATIN" not in name or not 127 < ord(c) < 768:
        return None
    base = ud.normalize("NFD", c)[0].lower()
    if "CIRCUMFLEX" in name:
        value = 2.6 if base == "a" else 0.8 if base in "ou" else 1.45
    elif "DIAERESIS" in name:
        value = 1.4 if base in "ei" else 0.4 if base == "u" else 0.7
    elif "ACUTE" in name:
        value = 0.07 if base == "e" else 0.6 if base == "u" else 0.35
        if base == "y":
            value = 0.0
    elif "GRAVE" in name:
        value = 1.0 if base == "a" else 0.9 if base == "i" else 0.7
    elif "TILDE" in name:
        value = 1.45
    elif "RING ABOVE" in name:
        value = 1.1 if base == "a" else 0.3
    elif "MACRON" in name:
        value = 0.9
    elif "CEDILLA" in name:
        value = 1.4 if base == "c" else 0.3
    else:
        value = 0.3
    if c.isupper():
        if base == "a":
            value = 2.8 if any(x in name for x in ("CIRCUMFLEX", "TILDE")) else 2.0
        elif (any(x in name for x in ("CIRCUMFLEX", "TILDE")) or
              ("DIAERESIS" in name and base in "ei")):
            value = 2.3
        else:
            value = 0.7 if "ACUTE" in name and base == "e" else 1.1
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, recent = (None, "") if first else carry[1:]
    token_id = int(prefix.token_ids[-1])
    text = prefix.token_strings[-1]
    glyph = text.strip(" ")
    fraction = recent.count("1") / max(1, len(recent))
    lead = SPACED_LEADS.get(token_id)
    # Single-byte tokens: IDs 126..129 encode UTF-8 starts C2..C5;
    # these two ranges encode continuation bytes 80..BF.
    bare_lead = token_id + 68 if 126 <= token_id <= 129 else None
    continuation = 94 <= token_id <= 123 or 222 <= token_id <= 255
    previous_out = ((lead[0], True) if lead else
                    (bare_lead, False) if bare_lead else None)
    value = 0.0
    if lead:
        value = 1.0 - 1.2 * fraction if lead[0] == 0xC2 else lead[1]
    elif continuation:
        value = 0.08
        if previous and 0xC2 <= previous[0] <= 0xC5:
            if previous[1]:
                value = 0.6 if previous[0] == 0xC2 else 1.2
            else:
                value = 0.55
    elif bare_lead == 0xC2:
        value = 1.0 - 1.2 * fraction
    elif glyph == "\xa0":
        value = 0.0 if text.startswith(" ") else max(0.0, 0.34 - 0.4 * fraction)
    elif glyph == "··":
        value = -0.5
    elif glyph in ("\x03", "\x0c", "\x0f"):
        value = 0.9
    elif len(glyph) == 1:
        value = latin_letter(glyph)
        if value is not None and text.startswith(" "):
            value += 0.6 if glyph.islower() else 0.15
            if "GRAVE" in ud.name(glyph, ""):
                value -= 0.45
                if glyph.lower() == "à":
                    value -= 0.2
            if glyph == "Å":
                value += 0.75
        if value is None:
            value = SYMBOLS.get(glyph, OTHER_VOWELS.get(glyph, 0.0))
    elif len(glyph) == 2 and text.startswith(" "):
        accented = [c for c in glyph if 127 < ord(c) < 256 and c.isalpha()]
        if len(accented) == 1:
            value = 0.25 * (latin_letter(accented[0]) or 0.0)
    if value >= 1.5:
        value *= 1.0 - 0.5 * fraction
    if first:
        value *= 0.5
    recent = (recent + ("1" if any(ord(c) > 127 for c in text) else "0"))[-32:]
    return (doc, previous_out, recent), float(value)

programs.haiku:
"""Layer 0, MLP down_proj component 2915: a detector for accented Latin-script characters.

What it responds to, in plain terms:
  * A single character from the Latin alphabet with a diacritic or special form
    (é, ü, ç, â, ö, ñ, ø, ß, æ, Á, Ł, ...). Activation about 0.5 on average (lowercase),
    about 1.0 for capitals, up to 3.
  * Common Latin-1 symbols such as © ® £ § ± ÷ ¼ ¿ ¡ º: a weaker response, about 0.23.
  * A broken-character token (U+FFFD, the piece of a UTF-8 character split across tokens).
    It responds like an accented letter when the text just before it is Latin script
    (mostly ASCII letters), and not at all in CJK, Hangul or other text.
Everything else (plain ASCII words, digits, spaces, punctuation, CJK) gets 0.

The program only uses the current token and the 16 tokens before it, so it is causal.
"""

import unicodedata

READS = ()

LATIN_ACCENT = 0.5    # typical activation of a lowercase accented Latin letter
LATIN_CAPITAL = 1.0   # capitals (À, Á, Â, É, Ö, ...) respond about twice as much
LATIN1_SYMBOL = 0.23  # Latin-1 punctuation and symbols
BROKEN_CHAR = 0.55    # a U+FFFD token in Latin-script context, scaled by Latin fraction
WINDOW = 16           # previous tokens used to judge the script of the context


def is_latin_accent(s):
    """One character, not ASCII, a letter whose Unicode name says LATIN (é, ö, Ł, ...)."""
    return len(s) == 1 and ord(s) > 127 and s.isalpha() and "LATIN" in unicodedata.name(s, "")


def is_latin1_symbol(s):
    """One character in the Latin-1 range (U+00A0 to U+00FF) that is not a letter."""
    return len(s) == 1 and 0xA0 <= ord(s) <= 0xFF and not s.isalpha()


def is_ascii_word(s):
    return len(s) > 0 and s.isascii() and s.isalpha()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    if is_latin_accent(token):
        value = LATIN_CAPITAL if token.isupper() else LATIN_ACCENT
    elif is_latin1_symbol(token):
        value = LATIN1_SYMBOL
    elif "�" in token:
        recent = [s.strip() for s in prefix.token_strings[-WINDOW - 1 : -1]]
        latin_share = sum(is_ascii_word(s) for s in recent) / max(1, len(recent))
        value = BROKEN_CHAR * latin_share
    else:
        value = 0.0
    return carry, float(value)

