"""A short-spelling feature, strongest for non-Latin p-like letters.

Cyrillic pe, Persian pe/gaf, Greek pi, and Indic pa/ga are strong triggers;
related labial syllables have smaller responses. Whitespace and case matter
for Cyrillic pe. Recent script distinguishes Greek prose from mathematical
pi. A byte piece is recognized if it completes one of these letters. Other
text is left at zero, omitting finer lexical and contextual effects.
"""
READS = ()

# Related consonant letters and syllables, with approximate response sizes.
FAMILIES = (
    ('گ', 1.6),                         # Persian gaf
    ('पਪਗ', 2.65),                      # Indic pa/ga
    ('बगਬ', 1.6),                       # Indic voiced stops
    ('ப', 3.4),                         # Tamil pa
    ('פ', 1.0),                         # Hebrew pe
    ('ป', 1.3), ('พ', 0.95),             # Thai p
    ('パピプペぱぴぷぺぽ', 0.68),         # Japanese p syllables
    ('ポフブ', 0.52), ('ふグ', 0.68),     # Japanese po/fu/bu/gu
    ('普', 1.1), ('帕', 1.3),            # Chinese pu/pa
    ('啪弗菲婆蒲旁', 0.63),              # Chinese labial syllables
    ('布佈葛', 0.53),                    # Chinese bu/ge
)
STRENGTH = {ch: v for letters, v in FAMILIES for ch in letters}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    greek, latin = (0.0, 0.0)
    if carry is not None and carry[0] == doc:
        _, greek, latin = carry
    raw = prefix.token_strings[-1]
    s = raw.strip()
    if s == '\ufffd':
        s = prefix.text_prefixes[-1][-1:]
    spaced = raw != s
    value = STRENGTH.get(s, 0.0)
    if s in ('п', 'П'):
        value = 1.34 if s == 'П' else (1.43 if spaced else 0.77)
    elif s in ('оп', 'еп'):
        value = 0.54 if spaced else 0.45
    elif s in ('ф', 'Ф'):
        value = 0.60 if spaced and s == 'ф' else 0.45
    elif s in ('π', 'Π', 'φ', 'Φ'):
        prose = greek > 2 and greek > latin
        value = 0.80 if prose else (0.18 if spaced else -0.10)
        if s in ('φ', 'Φ'):
            value = 0.63 if prose else 0.20
    elif s == 'پ':
        value = 2.14 if spaced else 1.81
    elif s in ('ب', 'ف', 'چ'):
        value = (0.67 if spaced else 0.41) if s == 'ب' else 0.45
    elif s in ('フィ', 'フェ', 'フォ'):
        value = 0.31 if s == 'フォ' else 0.7
    elif s in ('피', '포', '푸', '파', '페', '프'):
        value = 0.9 if s == '프' else 0.5
    elif s in ('p', 'P', 'f', 'g', 'G'):
        value = 0.15 if s == 'G' else (0.12 if spaced else 0.07)
    elif s in ('格', '格式'):
        value = 0.3
    elif 2 <= len(s) <= 4 and s.endswith('п'):
        value = 0.25
    elif 2 <= len(s) <= 3 and s.startswith(('п', 'П')):
        value = 0.17
    greek, latin = greek * 0.8, latin * 0.8
    for ch in s:
        greek += float(0x370 <= ord(ch) <= 0x3ff and ch.isalpha())
        latin += float(ch.isascii() and ch.isalpha())
    return (doc, greek, latin), float(value)

