programs.sol:
"""A period-following digit detector with a short fading tail.

The strongest response is the first fractional/version digit, especially zero.
Its magnitude decreases as more context is available. The next two decimal
digits and spaced ellipses produce smaller responses. Repeated periods in a
single token are not decimal points. Unmodelled activations are set to zero.
"""
READS = ()
DIGITS = '0123456789'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, older, depth, position = '', '', 0, 0
    else:
        _, previous, older, depth, position = carry
        position += 1
    token = prefix.token_strings[-1]
    digit = len(token) == 1 and token in DIGITS
    value = 0.0
    if digit and previous.endswith('.'):
        if previous.endswith('..'):
            value = -0.10
            depth = 0
        else:
            numeric = bool(older) and older[-1] in DIGITS
            amplitude = (1.04 if numeric else 0.60)
            amplitude += 0.22 / (1.0 + position / 40.0)
            if token == '0':
                amplitude += 0.35 if numeric else 0.55
            if position == 1:
                amplitude = 2.20 if token == '0' else 1.65
            value = -amplitude
            depth = 1
    elif digit and depth:
        value = -0.145 * 0.18 ** (depth - 1)
        depth += 1
    else:
        depth = 0
        if token == ' .' and previous.strip() == '.':
            value = -0.35
    return (doc, token, previous, depth, position), float(value)

"""Approximate a local English clause-linking response.

The important training examples mostly contained lowercase 'that', wh-words,
and 'because'. These get negative predictions, strengthened after copulas and
proposition-expressing words, weakened by capitalization, coordination,
punctuation, and demonstrative uses. 'Who'/'which' have a contrasting relative-
clause rule; quantities after copulas give smaller positive predictions, while
'due' gives a negative one. Unlisted tokens are zero: idiosyncratic lexical
responses and full syntactic parsing are deliberately omitted.

Only the last 80 decoded characters are kept, reset between documents.
"""
import re
READS = ()


def forms(roots):
    result = set()
    for r in roots.split():
        result.update((r, r+'s', r+'ed', r+'ing'))
        if r.endswith('e'):
            result.update((r+'d', r[:-1]+'ing'))
        if r.endswith('y') and r[-2] not in 'aeiou':
            result.update((r[:-1]+'ies', r[:-1]+'ied'))
    return result

COPULAS = set('is was are were be been being am'.split()) | {"'s", '’s'}
PREPOSITIONS = set('of in on at to for from with by into over under through '
                   'about after before than like'.split())
COORDINATORS = set('and but or nor yet if then since until while when because'.split())
EVIDENCE = forms('show find suggest indicate reveal demonstrate explain imply '
                 'propose') | {'found', 'shown'}
ASSERTIONS = forms('believe assume ensure conclude state note report argue suppose')
PROPOSITIONS = set('fact theory assumption idea evidence conclusion reason '
                   'possibility chance way extent sense given known possible '
                   'probable likely'.split())
THOUGHT = forms('know see think say mention remember check verify wonder ask')
THOUGHT |= {'knew', 'said', 'seen', 'saw', 'thought'}
ACTIONS = set('do did does use make put take keep get try have all only just'.split())
BASE = {'that': -0.97, 'what': -1.4, 'how': -1.35, 'why': -1.6,
        'where': -1.04, 'because': -0.88, 'when': -0.4, 'whether': -0.44}
QUANTITIES = set('some many most much only just either certain'.split())
EXPLANATIONS = forms('explain describe illustrate')
COPULAR = {'what': -3.55, 'how': -2.9, 'why': -3.5, 'where': -2.2,
           'because': -1.95, 'when': -1.55, 'whether': -1.2}


def value(s, tail):
    word = s.strip()
    w = word.lower()
    if w not in BASE and w not in QUANTITIES and w not in ('which', 'who', 'due'):
        return 0.0
    if word[:1].isupper() and not word.isupper():
        return {'who': 0.59, 'which': 0.36, 'because': -0.14,
                'when': 0.05, 'how': 0.05}.get(w, 0.0)
    if not s.startswith(' '):
        return {'that': -0.51, 'what': -0.39, 'how': -0.29, 'why': -0.6,
                'where': -0.11, 'because': -0.37, 'when': -0.06,
                'whether': -0.06, 'who': 0.35, 'which': 0.15}.get(w, 0.0)
    words = re.findall(r"[A-Za-z]+|['’]s|[^\w\s]", tail)
    prev = words[-1] if words else ''
    p = prev.lower()
    copula = p in COPULAS
    boundary = not p or p in ',;.!?' or p in COORDINATORS
    if w in QUANTITIES:
        if copula:
            if w == 'most':
                v = 0.9
            else:
                v = 0.5 if w in ('some', 'only', 'either', 'certain') else 0.4
            return v * (1.0 if p in ('is', 'are') else 0.65)
        return 0.08 if w in ('some', 'most', 'many', 'either', 'certain') else 0.0
    if w == 'due':
        return (-0.9 if p == 'is' else -0.6) if copula else 0.06
    if w in ('which', 'who'):
        if boundary:
            return 0.48 if w == 'who' else 0.18
        return 0.08 if p in PREPOSITIONS or p in THOUGHT else -0.18
    if boundary:
        return {'because': -0.3, 'when': 0.07, 'whether': -0.02}.get(w, -0.1)
    v = BASE[w]
    if copula:
        if w == 'that':
            return -2.37 if p == 'is' else -2.0 if p == 'was' else -1.6
        v = COPULAR[w]
        subject = words[-2].lower() if len(words) > 1 else ''
        if p == 'is' and subject in ('this', 'that', 'here', 'there'):
            v -= 0.6
        elif p not in ('is', "'s", '’s'):
            v *= 0.8
        return v
    if w == 'that':
        if p in PREPOSITIONS:
            return -0.4 if p == 'to' else -0.16
        if p in ACTIONS or p in ('what', 'that'):
            return -0.44
        if p in ('so', 'sure', 'as', 'except', 'maybe'):
            return -0.6 if not prev[:1].isupper() else -0.24
        if p == 'such':
            return -0.93
        if p in ('mean', 'means', 'meant', 'meaning'):
            return -2.2 if p == 'means' else -1.55
        if p in EVIDENCE:
            v = -1.55 - (0.15 if p.endswith('s') else 0.0)
        elif p in ASSERTIONS:
            v = -1.25
        elif p in PROPOSITIONS:
            v = -1.46
        if p in THOUGHT:
            v = -0.52 if p in ('see', 'saw') else -0.8
    else:
        if p == 'sure':
            return -0.06
        if p in THOUGHT:
            return -0.2 if w in ('where', 'whether') else -0.55
        if p in EXPLANATIONS:
            return -2.3 if w == 'why' else -2.1
        if p in ('matter', 'so'):
            return -0.6
    if not prev.isalpha():
        v *= 0.5
    elif prev[:1].isupper():
        v *= 0.75
    return v


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    return (doc, (tail+s)[-80:]), float(value(s, tail))

programs.haiku:
"""Layer 0 MLP down-projection component 2923: a "cor-" word detector.

The component reads the current token and answers with a negative number when that token
starts a word spelled with "cor" (Cor, cor, COR, corporate, corpus, coronary, correlation,
correct, ...). Strongest on "cor"/"corp"/"coro" words, a bit weaker on "correlat-" words,
weaker still on other "corr-" words and on "encour-" words, and weakest on "incor-" words.
Words that merely share the letters, or that begin with "cor" but are unrelated (core, cord,
corn, corner, court), stay at 0. Everything else is 0. Values are hand-set means of the
activation per word family, measured on training text.
"""

import re

READS = ()

# Words that start with "cor" but that this component ignores.
QUIET = {"core", "cord", "corn", "corner", "cork", "cort", "cortex", "cortical",
         "cortisol", "corey", "cory", "cornel", "cornell", "cornwall", "corm", "cornerstone"}


def _word(token):
    """The token as a lowercase word, dropping leading spaces and punctuation."""
    return re.sub(r"^[^a-zа-я]+", "", token.strip().lower())


def step(carry, prefix, upstream):
    x = _word(prefix.token_strings[-1])
    if x in QUIET:
        value = 0.0
    elif x == "cor" or x.startswith(("corp", "cors", "coro", "cora")):
        value = -3.4
    elif x.startswith("correlat"):
        value = -3.0
    elif x.startswith(("correct", "incorrect")):
        value = -1.8
    elif x.startswith("corr"):
        value = -2.2
    elif x.startswith("encour"):
        value = -2.2
    elif x.startswith("incor"):
        value = -1.3
    elif x.startswith("кор"):
        value = -1.8
    else:
        value = 0.0
    return carry, value

"""Time-anchor words: the component goes negative on words that pin a statement to the
present or to a nearby day, most strongly on "today" (and its translations), then on
"yesterday", "tonight", "tomorrow", and more weakly on "now", "currently", "recently",
"daily" and similar, and weakly on plain time-period nouns ("day", "week", "month").
Everywhere else it sits near zero.

The program reads only the newest token. It returns a negative number for those words,
scaled by how strongly the component responds to each group, and 0 otherwise.
"""

READS = ()

TODAY = {"today", "сегодня", "今天", "今日", "今日は", "오늘", "oggi", "heute", "hoy", "dziś"}
NEAR_DAYS = {"yesterday", "tonight", "tomorrow", "nowadays", "昨天", "昨日"}
NOW = {"now", "currently", "recently", "daily", "everyday", "presently", "contemporary",
       "соврем", "今", "最近", "近期", "今年", "现在", "目前", "当今"}
PAST_OR_RECENT = {"ago", "recent", "anymore", "soon", "-day", "day"}
PERIODS = {"week", "month", "year", "morning"}


def _value(word):
    if word == "today":
        return -9.0
    if word in TODAY:
        return -4.0
    if word in NEAR_DAYS:
        return -3.5
    if word in NOW:
        return -1.3
    if word in PAST_OR_RECENT:
        return -0.9
    if word in PERIODS:
        return -0.4
    return 0.0


def step(carry, prefix, upstream):
    # drop punctuation attached to the token (".Today" -> "today")
    word = prefix.token_strings[-1].strip().lower().strip(".,;:!?'\"-")
    return None, float(_value(word))

"""Layer-0 MLP down-projection component 2925: the English word "general".

What it does: when the current token is "general" (any capitalisation, as in
" general", " General", "GNU General Public License"), it writes a strong
signal into the residual stream. Words built from the same stem get smaller
signals, and a few near-synonyms of "general" get a small one. The activation
depends almost only on the current token, not on the surrounding text.

Approximate activation by token (the program's prediction):
  general / General / GENERAL        about 7   (the core word)
  generally                          about 5
  general in other languages (一般, 일반, général, geral, общ) about 2.5-6
  generic, gener                     about 3-3.5
  gen, Gen (fragments)               about 1.5
  generate, generator, generation    about 1
  usually, typically, overall, special, basically, broad,
  ordinary, regular, normal, always, standard, simply
                                     about 1
Every other token gives 0.
"""

READS = ()

CORE = {"general", "generals", "eneral"}
# "general" in other languages, and Chinese words for general/common/universal
TRANSLATIONS = {
    "一般": 6.0, "一般的": 4.5, "般": 5.0, "일반": 5.0, "通用": 3.0, "普遍": 2.0,
    "普通": 2.0, "général": 4.0, "géné": 4.0, "geral": 3.0, "общ": 2.4, "вообще": 2.5,
}
NEAR_SYNONYMS = {
    "usually", "typically", "overall", "special", "basically", "broad", "broadly",
    "ordinary", "ordinarily", "regular", "normal", "normally", "standard", "always",
    "simply", "universal", "usual", "basic",
}


def word_value(token):
    """Predicted activation for one token string."""
    w = token.strip().strip("-/._").lower()
    if w in TRANSLATIONS:
        return TRANSLATIONS[w]
    if w in CORE:
        return 7.0
    if w == "generally":
        return 5.0
    if w == "gener":
        return 3.5
    if w.startswith("generic"):
        return 3.0
    if w.startswith("generat"):
        return 1.0
    if w in ("gen", "geme", "éné"):
        return 1.5
    if w in NEAR_SYNONYMS:
        return 1.0
    return 0.0


def step(carry, prefix, upstream):
    """Stateless: the value depends only on the newest token."""
    return carry, float(word_value(prefix.token_strings[-1]))

