"""Layer-0 MLP down_proj component 2926: a negative "test/experiment outcome" detector.

What it does: it goes negative on words that name the outcome, setup or
pass/fail status of a test, study or scheduled event. Its strongest response is
the word "result(s)" right after a test- or experiment-related word, e.g. the
"result" in Rust's "test result: ok." or "experimental results". Weaker
negative values go to outcome/procedure nouns elsewhere (results, plan, place,
process, time, conducted, begins) and pass/fail/suite words. Everything else
predicts 0.
"""

OUTCOME = {"result", "results", "outcome", "outcomes", "结果", "suite", "suites"}
PROCEDURE = {
    "plan", "plans", "方案", "地点", "场地", "过程", "过程中", "时间", "内容", "规则",
    "rules", "apparatus", "conducted", "begins", "began", "starts", "started",
    "carried", "setup", "procedure",
}
PASS_FAIL = {"pass", "passed", "passes", "fail", "failed", "fails"}
TEST_CONTEXT = {
    "test", "tests", "testing", "experiment", "experimental", "simulation",
    "measurement", "study", "survey", "trial", "exam", "research", "clinical",
    "assay", "lab", "running", "run", "pass", "suite", "suites",
    "实验", "测试", "考试", "研究",
}
# (base value, extra value when preceded by a test/experiment word)
WEIGHTS = {"outcome": (-0.12, -1.35), "procedure": (-0.15, -0.73), "pass_fail": (-0.10, -0.56)}

# nouns for the data, case or setting of a test, negative only right after a test word
SETTING = {"data", "case", "config", "script", "instance", "session", "log", "center",
           "room", "site", "environment", "conditions", "parameters", "questions", "logic"}
SETTING_AFTER_TEST = -0.5
READS = ()


def _core(token):
    return token.strip().lower()


def step(carry, prefix, upstream):
    cur = _core(prefix.token_strings[-1])
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = _core(prefix.token_strings[-2]) if same_doc else ""
    if cur in OUTCOME:
        group = "outcome"
    elif cur in PROCEDURE:
        group = "procedure"
    elif cur in PASS_FAIL:
        group = "pass_fail"
    elif cur in SETTING and prev in TEST_CONTEXT:
        return carry, SETTING_AFTER_TEST
    else:
        return carry, 0.0
    base, extra = WEIGHTS[group]
    value = base + (extra if prev in TEST_CONTEXT else 0.0)
    return carry, float(value)

