    'he': (-3.65, -3.00, -0.53, -2.64),
    'him': (-4.30, -3.25, -3.20, -3.00),
    'himself': (-2.95, -2.95, -2.10, -2.35),
    'her': (-3.35, -2.63, -0.95, -2.15),
    'she': (-2.42, -1.80, -1.60, -1.53),
    'hers': (-1.74, -1.40, -1.20, -1.40),
    'herself': (-1.49, -1.20, -1.05, -1.20),
    'their': (-1.90, -1.70, -1.55, -1.59),
    'they': (-1.03, -0.92, -0.79, -0.78),
    'them': (-1.07, -0.90, -0.75, -0.85),
    'themselves': (-0.54, -0.44, -0.38, -0.44),
    'its': (-1.29, -1.03, -0.14, -0.80),
    'itself': (-0.28, -0.22, -0.20, -0.22),
