    'man': -1.31, 'men': -1.08, 'boy': -2.29, 'boys': -1.29,
    'guy': -1.91, 'guys': -0.85, 'male': -0.81, 'males': -0.62,
    'son': -0.83, 'father': -0.93, 'brother': -0.80,
    'husband': -1.26, 'sir': -0.91, 'mr': -1.32,
}
# Russian, German, French, Spanish, Italian, and Portuguese forms.
OTHER_PRONOUNS = {
    'он': -1.34, 'его': -2.31, 'ему': -1.83, 'него': -1.22,
    'ее': -1.18, 'её': -1.18, 'их': -1.03, 'они': -0.65,
    'seine': -1.60, 'seiner': -1.76, 'seinem': -1.74,
    'seinen': -1.43, 'ihm': -1.29, 'ihn': -0.80,
    'ihre': -0.93, 'ihrer': -0.82, 'ihrem': -0.94,
    'lui': -1.54, 'leur': -0.85, 'leurs': -0.78, 'ils': -0.22,
    'su': -0.31, 'sus': -0.43, 'suo': -1.16, 'sua': -0.58,
    'ele': -0.30,
