PREPOSITIONS = set('''
of in to for with on by from at about as into during against around
after before without over under through
'''.split())
SUBORDINATORS = set('''
that where when if because what which though while how since
whether although unless
'''.split())
COORDINATORS = {'and', 'or', 'but', 'nor'}


def chinese_reference(word):
