        return -1.35
    if '她们' in word or '她們' in word:
        return -1.1
    if '他的' in word:
        return -3.65
    if '她的' in word:
        return -2.3
    # Standalone pronouns, or pronouns fused with a short linking word.
    linked = len(word) <= 4 and word[:1] in '给让跟但看对为与和将是在'
