        return -5.0 if word.startswith('在他') else -3.15
    if word.startswith('她') or (linked and '她' in word):
        return -2.2
    return -0.51 if word == '它' else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous, references, last_reference = 0, '', 0, -100
