        forms = PRONOUNS[lower]
        capitalized = word.istitle()
        index = (0 if spaced else 2) + int(capitalized)
        value = forms[index]
        if fused_punctuation:
            value = forms[int(capitalized)] * (0.75 if capitalized else 0.6)
        elif word.isupper():
            if not spaced:
                value = forms[0] * 0.08
            elif lower in ('they', 'their', 'them'):
                value = forms[0] * 0.9
            elif lower in ('he', 'him'):
                value = forms[0] * 0.25
            else:
                value = forms[0] * 0.5
        elif not spaced and not capitalized and lower in ('he', 'her', 'its'):
            if not previous or not previous[-1].isalnum():
                value = forms[0] * 0.62
    elif lower in MALE_WORDS:
        value = MALE_WORDS[lower]
        if lower == 'mr':
