            prior = previous.strip().lower()
            if prior in PREPOSITIONS:
                factor += 0.085
            elif prior in SUBORDINATORS:
                factor += 0.14
            elif prior in COORDINATORS:
                factor -= 0.06
            factor -= 1.95 * references / position
            if position - last_reference < 8:
                factor -= 0.08
        value *= max(0.3, factor)
