        word = token[1:]
        if word.islower():
            if len(word) == 1:
                value = 0.42 if word in INDEX_LETTERS else 0.65
            else:
                value = 0.90 - (0.075 if len(word) == 2 else 0.0)
        elif word.isupper():
            value = 0.42 if len(word) == 1 else 0.51
        else:
            value = 0.41
        if underscore_word(previous):
            value += 0.16
        if 0 < len(previous.strip()) <= 2:
            value -= 0.086
        if previous and not previous[-1].isalnum():
            value -= 0.11
    elif token == '_':
        name = previous.strip()
        value = -0.16 if name.isalpha() and name.isupper() else 0.03
    elif token.startswith('</') and token.endswith('>'):
        value = 0.12
    elif token and set(token) == {'_'}:
        value = 0.035
    elif token.isascii() and token.isalpha() and underscore_word(previous):
        value = 0.04
    return (doc, token), float(value)

"""Approximate a negative colon response from visible punctuation shape.

Colons merged with letters or symbols are strongest. URL separators,
namespace separators and line endings have their own weaker strengths.
Quotes, assignments, brackets and leading spaces adjust the response.
A bare colon is weaker after numbers, function words or prose introducers,
and stronger after capitalized tokens or field labels. Previous-token rules
never cross a document boundary. Most noncolon tokens are predicted near zero.
Training measurements show this dominant colon effect; the fixed amplitudes
are rounded estimates and do not capture every token-specific residual.
"""
READS = ()

INTRODUCERS = frozenset({
    'below', 'said', 'says', 'say',
    'include', 'includes', 'including', 'example', 'examples',
    'answer', 'solution',
})
FUNCTION_WORDS = frozenset({
    'is', 'are', 'was', 'were', 'be', 'as', 'of', 'with',
    'this', 'that', 'these', 'those', 'like',
})
FIELD_LABELS = frozenset({
    'name', 'type', 'date', 'time', 'source', 'location', 'host',
    'title', 'size', 'width', 'height', 'value', 'id', 'key', 'color',
    'error', 'warning', 'note', 'debug', 'info', 'filename', 'file',
    'email', 'url',
})


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    colon = next((i for i, c in enumerate(token) if c in ':：'), -1)
    if colon < 0:
        return None, -0.002
    before, after = token[:colon], token[colon + 1:]
    spaced = 0.9 if token[:1].isspace() else 0.0
    closing = ')' in before
