    if '://' in token:
        value = -2.2 if ':///' in token else -1.65
    elif '::' in token:
        value = -0.97
    elif ':' in after or '：' in after:
        value = -0.5
    elif after[:1].isalpha():
        value = -4.4
    elif before.strip() and before.strip()[-1] in '[({<>?':
        value = -0.8
    elif after[:1] in {'"', "'", '“'}:
        value = -3.0 + spaced
        if '"' in before or "'" in before:
            value += 0.5
        if '\n' in after:
            value += 0.6
        if token[colon] == '：':
            value = -1.6
    elif '\n' in after:
        n = after.count('\n')
        if n >= 3:
            value = -1.25
        else:
            value = -0.74 if n == 1 else -0.6
        if closing:
            value = -0.3 if n == 1 else -0.44
    elif after.startswith('\\'):
        value = -2.35 if len(after) == 1 else -3.5
        if closing:
            value = -1.36
    elif after.startswith('='):
        value = -0.82 if spaced else -1.57
    elif after:
        value = -1.5 if after.startswith('**') else -3.4 + spaced
    else:
        if closing:
            value = -0.61
        elif ']' in before or '*' in before:
            value = -0.7
        elif '"' in before or "'" in before:
            value = -1.02
        else:
            # Bare-colon context: only the previous token in this document.
            previous = ''
            if (prefix.position > 0 and
                    prefix.document_ids[-1] == prefix.document_ids[-2]):
                previous = prefix.token_strings[-2].strip()
            word = previous.lower()
            value = -1.03
            if previous.isdigit():
                value += 0.1
            if previous[:1].isupper() or previous.startswith('.'):
                value -= 0.14
            if not previous:
                value += 0.44
            if word in INTRODUCERS:
                value += 0.65
            if word in FUNCTION_WORDS:
                value += 0.35
            if word in FIELD_LABELS:
                value -= 0.24
            if word in {'following', 'follows'}:
                value = 0.03
    return None, value

"""Sentence punctuation joined to a line or paragraph break.

Training responses concentrate on these joined tokens, not bare newlines.
Full stops respond most strongly; questions and exclamations also respond.
Exactly two newlines strengthen the response. Extra punctuation around a
full stop, leading spaces, carriage returns, and ellipses weaken it.
Earlier sentence-ending line breaks reduce the response logarithmically;
the count resets at document boundaries. Ordinary words are left at zero,
so word-specific variation is deliberately not explained.
"""
import math

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    endings = carry[1] if carry is not None and carry[0] == doc else 0
    token = prefix.token_strings[-1]
    mark, newline, _ = token.partition('\n')
    mark = mark.rstrip('\r ')
    active = False
    if newline and not any(c.isalnum() for c in mark):
        active = True
        if '..' in mark or '…' in mark:
            value, active = 0.10, False
        elif '.' in mark:
            value = 0.79 if mark.strip() == '.' else 0.63
            if not mark.endswith('.'):
                value = 0.43
        elif '。' in mark:
            value = 0.64
        elif '?' in mark or '？' in mark:
            value = 0.59
        elif '!' in mark or '！' in mark:
            value = 0.64
        else:
            value, active = 0.0, False
        if active:
            breaks = token.count('\n')
            if breaks == 2:
                value += 0.23
            elif breaks >= 3:
                value -= 0.09
            value -= 0.19 if '\r' in token else 0.0
            value -= 0.22 if token.startswith(' ') else 0.0
            value -= 0.19 * math.log1p(endings)
    else:
        bare = token.strip()
        value = -0.015 if bare in ('.', '。') else 0.0
        if bare in ('?', '!', '？', '！'):
            value = -0.04
        elif bare.isdigit():
            value = -0.005
    return (doc, endings + active), float(value)

