"""Approximate a sparse response to several recognizable word endings.

The strongest sampled cases are Romance-style -ale/-ales and -elle endings,
alongside the broader -al family; a few are Cyrillic -альн- adjectives. The
small carry joins pieces of the current word, but never uses future text.
"""

import unicodedata

READS = ()

CYRILLIC_ADJECTIVE_ENDINGS = (
    "альный", "альная", "ального", "альной", "альную",
    "альные", "альных", "альным", "альными", "ально", "альн",
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    word = carry[1] if carry is not None and carry[0] == doc else ""
    for char in prefix.token_strings[-1].lower():
        if char.isalpha():
            word = (word + char)[-20:]
        else:
            word = ""

    plain = "".join(
        char for char in unicodedata.normalize("NFKD", word)
        if not unicodedata.combining(char)
    )

    if word.endswith(CYRILLIC_ADJECTIVE_ENDINGS):
        value = -0.45
    elif plain.endswith("ales"):
        value = -0.54
    elif plain.endswith("elle"):
        value = -0.35
    elif plain.endswith("ale"):
        value = -0.25
    elif plain.endswith("ell"):
        value = -0.11
    elif plain.endswith("aux"):
        value = -0.14
    elif plain.endswith("al"):
        value = -0.02
    else:
        value = 0.0
    return (doc, word), value

