"""Detect ACT and its lexical neighborhood.

ACT itself is much stronger than action, activation, actors, or work. Its
capitalization matters, and most embedded act fragments are weaker than
standalone forms. A one-token echo appears on OF, selected prepositions,
and split inflection suffixes. State resets at document boundaries.
"""
READS = ()


def lexical_response(text, inside_word=False):
    word = text.strip().strip('._-/()[]{}\"\'').lower()
    if word in {'act', 'acts', 'acted', 'acting'}:
        original = text.strip().strip('._-/()[]{}\"\'')
        if word == 'act' and original == 'Act':
            return 8.3
        if word == 'act' and original == 'ACT':
            return 2.5 if inside_word else 5.9
        if word == 'acting':
            return 3.4 if inside_word else 5.4
        if inside_word:
            return 4.0 if word == 'act' else 2.0
        return 7.2 if word == 'act' else 6.9
    if word in {'react', 'reacts', 'reacted', 'reacting'}:
        return 3.3 if word == 'react' else 2.0
    if word in {'enact', 'enactment', 'enacted'}:
        return 3.0 if word == 'enacted' else 4.0
    if word in {'activation', 'activations', 'activ'}:
        return 2.1
    if word in {'activate', 'activated', 'activating', 'activates', 'deactivate'}:
        return 1.7
    if word in {'actor', 'actors', 'actress', 'actresses'}:
        return 1.5
    if word in {'interact', 'interacts', 'interacting'}:
        return 1.8
    if word == 'actual':
        return 1.4
    if word in {'action', 'actions', 'actually', 'interactive', 'actively',
                'interaction', 'interactions', 'reaction', 'reactions'}:
        return 1.0
    if word in {'active', 'inactive', 'reactive', 'proactive'}:
        return 0.7
    if word in {'activity', 'activities'}:
        return 0.15
    if word == 'work':
        return 0.84
    if word in {'works', 'working', 'operate', 'operating'}:
        return 0.72
    if word == 'worked':
        return 0.5
    if word in {'legislation', 'statute', 'statutes', 'legisl', 'legislature',
                'legislative'}:
        if word == 'legislation':
            return 1.9
        return 1.3 if word.startswith('statut') else 0.85
    if word in {'behave', 'behaves', 'behaving'}:
        return 1.4
    if word == 'lact':  # A spelling echo, not a word about action.
        return 1.7
    # Action-related roots in Russian, Chinese, and Japanese.
    if word in {'действ', 'ейств', 'действия', '采取', '行动', '行動', '活'}:
        return 2.0
    return 0.0


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    same_doc = carry is not None and carry[0] == prefix.document_ids[-1]
    inside = bool(same_doc and carry[1] and text and
                  carry[1][-1].isalpha() and text[0].isalpha())
    base = lexical_response(text, inside)
    previous = carry[2] if same_doc else 0.0
    # Carry the signal across an action's complement or split inflection.
    if text == ' of':
        echo = 0.44 * previous
    elif text in {' to', ' on', ' as'}:
        echo = 0.06 * previous
    elif text in {'ing', 'ed', 's'}:
        echo = 0.6 * previous
    else:
        echo = 0.0
    return (prefix.document_ids[-1], text, base), base + echo

