programs.sol:
"""Contrast kanji content with Japanese grammatical scaffolding.

Recent kana establish Japanese context (rather than Chinese, which shares kanji).
In that context, kanji-only tokens are negative, especially at the start of
a kanji run; multi-kanji tokens are stronger. Case particles and Japanese
punctuation are positive. Mixed kanji/kana words and
ordinary phonetic text have much smaller contributions. For a split Unicode
character, an unfinished fragment is more negative than its completing fragment;
completed kana is nearly neutral. State resets at each document boundary.
"""
READS = ()

# Japanese case/topic/additive particles; notably, 'の' and 'で' are much weaker.
PARTICLES = {'は': 1.25, 'が': 1.55, 'を': 1.3, 'に': 0.85,
             'と': 0.75, 'も': 0.8, 'や': 0.85, 'の': 0.06, 'で': 0.1}
PUNCTUATION = {'、': 1.8, '。': 0.9, '・': 1.4,
               '「': 0.8, '『': 0.7, '…': 1.0}
COPULAS = {'です', 'だ', 'である'}
DO_VERBS = {'する', 'した', 'して', 'し', 'します', 'しました'}


def is_kanji(c):
    return '\u3400' <= c <= '\u9fff'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        density, previous_kanji = 0.0, False
    else:
        density, previous_kanji = carry[1:]
    raw = prefix.token_strings[-1]
    s = raw.strip()
    kana = any('\u3041' <= c <= '\u309f' or
               '\u30a1' <= c <= '\u30fa' for c in s)
    density = 0.95 * density + float(kana)
    japanese = density / (density + 2.0)
    kanji = bool(s) and all(is_kanji(c) for c in s)
    if kanji:
        weight = -2.9 + 0.55 * previous_kanji - 0.45 * (len(s) > 1)
        value = japanese * weight
    elif s in PARTICLES:
        value = PARTICLES[s]
    elif s in PUNCTUATION:
        value = japanese * PUNCTUATION[s]
        if '\n' in raw:
            value *= 0.75
    elif s in COPULAS:
        value = 0.6
    elif s in DO_VERBS:
        value = 0.35
    elif s == 'という':
        value = 0.75
    elif kana:
        value = -0.2 if any(is_kanji(c) for c in s) else 0.1
    elif '\ufffd' in s:
        # Joint decoding distinguishes an unfinished UTF-8 character from
        # a fragment that completes a kanji or kana character.
        end = prefix.text_prefixes[-1][-1:]
        if end == '\ufffd':
            value = -1.0 * japanese
        elif is_kanji(end):
            value = -0.5 * japanese
        else:
            value = 0.0
    elif s.startswith('<|'):
        value = 0.03 + 0.5 * japanese
    elif not s:
        value = japanese * (0.4 if '\n' in raw else 0.25)
    else:
        value = 0.1 * japanese
    return (doc, density, kanji), float(value)

programs.haiku:
"""Component layers.0.mlp.down_proj:2937 (layer 0 MLP, down projection).

What it does: it is a "kanji starts a word after kana" detector with the sign flipped.
- A kanji (CJK ideograph) token that directly follows a hiragana or katakana token (a
  particle such as の/を/に/は, or okurigana) pushes it strongly negative (about -2.5).
- Other kanji, mostly ones following kanji, get a small negative value.
- Kana particles が, を, は, に, も, と, や push it mildly positive (about +0.7 to +1.5).
- Everything else is about 0.
The program only looks at the current token and the one before it.
"""

READS = ()

PARTICLE_VALUE = {"が": 1.5, "を": 1.3, "は": 1.2, "に": 0.9, "や": 0.9, "も": 0.8, "と": 0.7}


def _kind(s):
    if not s or "�" in s:
        return "other"
    if all("一" <= c <= "鿿" for c in s):
        return "kanji"
    if all("぀" <= c <= "ゟ" for c in s):
        return "hiragana"
    if all("゠" <= c <= "ヿ" for c in s):
        return "katakana"
    return "other"


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    kind = _kind(cur)
    if prefix.position == 0:
        prev = ""
    else:
        prev = _kind(prefix.token_strings[-2])
    if kind == "kanji":
        if prev in ("hiragana", "katakana"):
            return carry, -2.5
        return carry, -0.25
    if kind == "hiragana":
        return carry, PARTICLE_VALUE.get(cur, 0.0)
    return carry, 0.0

programs.luna:
"""Estimate activation from the current and immediately previous token.

Common Japanese particles get a positive estimate, as do the comma, interpunct,
period, and the forms “です” and “から”. A Han-only token after Hiragana gets a
strong negative estimate; other Han gets a smaller negative. Remaining
Hiragana gets a small positive estimate, Katakana gets zero, and ordinary text
is near zero. These are broad script and grammar cues, not word meanings.
"""
READS = ()
JAPANESE_PARTICLES = frozenset({"が", "を", "は", "に", "や", "と", "も"})


def script(text):
    text = text.strip().replace("�", "")
    has_han = any("\u3400" <= ch <= "\u9fff" for ch in text)
    has_hira = any("\u3040" <= ch <= "\u309f" for ch in text)
    has_kata = any("\u30a0" <= ch <= "\u30ff" for ch in text)
    return has_han, has_hira, has_kata


def step(carry, prefix, upstream):
    surface = prefix.token_strings[-1].strip()
    has_han, has_hira, has_kata = script(surface)

    previous = ""
    if len(prefix) > 1 and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2].strip()
    _, previous_has_hiragana, _ = script(previous)

    if surface in JAPANESE_PARTICLES:
        value = 1.2
    elif surface == "、":
        value = 1.0 if previous_has_hiragana else 0.8
    elif surface == "。":
        value = 0.2
    elif surface == "・":
        value = 1.2
    elif surface == "です":
        value = 0.6
    elif surface == "から":
        value = 0.45
    elif has_han and not has_hira and previous_has_hiragana:
        value = -2.6
    elif "�" in surface and previous_has_hiragana:
        value = -1.4
    elif has_han and has_hira:
        value = -0.13
    elif has_han:
        value = -0.22
    elif has_hira:
        value = 0.12
    elif has_kata:
        value = 0.0
    elif "�" in surface:
        value = -0.15
    else:
        value = 0.0
    return None, float(value)

programs.haiku:
"""layers.0.mlp.down_proj:2938 — a weak, word-level "academic register" detector.

What it does: the component's activation is almost entirely a function of the current
word. It is positive on words from scientific-paper prose and on the closing think tag
"</think>", and slightly negative on a set of everyday words. Everything else is 0.
The predicted value depends only on the newest token (no state is carried).

Values are the mean activation of each word group in a sample of training text, so the
program predicts the average value for each group rather than per-word values.

Plain-language reading:
  * strongest positive: "results", "authors", "Institute", "effect(s)", "mechanism(s)",
    "research", "study", "manuscript", "doi" (the vocabulary of papers and reports);
  * the "</think>" token, which closes a reasoning block, is clearly positive;
  * a set of everyday words (online, too, book, off, various, every, ...) is mildly negative.
"""

READS = ()

# Words that open or carry research prose: results, authors, institutes, findings.
RESULTS_AND_AUTHORS = {"results", "result", "authors", "author", "institute", "institutes"}
# Words about causes and effects of a finding.
EFFECTS_AND_MECHANISMS = {"effect", "effects", "mechanism", "mechanisms", "findings"}
# General scientific-paper vocabulary.
PAPER_WORDS = {
    "research", "study", "studies", "studied", "manuscript", "doi", "analysis", "analyses",
    "approach", "method", "methods", "scientific", "sciences", "science", "data", "model",
}
# Everyday words that sit slightly below zero.
EVERYDAY_WORDS = {
    "online", "too", "book", "books", "off", "various", "every", "life", "power", "world",
    "rare", "young", "medical", "information", "all", "new", "called", "try", "along",
}

VALUE = {
    "results": 0.06,
    "effects": 0.14,
    "paper": 0.035,
    "think": 0.27,
    "everyday": -0.055,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == "</think>":
        return carry, VALUE["think"]
    word = token.strip().lower()
    if word in RESULTS_AND_AUTHORS:
        return carry, VALUE["results"]
    if word in EFFECTS_AND_MECHANISMS:
        return carry, VALUE["effects"]
    if word in PAPER_WORDS:
        return carry, VALUE["paper"]
    if word in EVERYDAY_WORDS:
        return carry, VALUE["everyday"]
    return carry, 0.0

