programs.sol:
"""A local ordinal-position and successive-occurrence signal.

Most ordinal words, attached numeric suffixes, and introductions are positive.
Time/event nouns amplify preceding ordinals ('first time', 'next year'). List
transitions and structural constructions ('firstly', 'first thing/place') are
negative. Casing, token boundaries, and ordinal form adjust the strengths.
Small multilingual lexicons cover related forms. State keeps two preceding
representations, joining split ordinals, and resets at document boundaries.
Uncovered constructions receive zero; longer-range effects are not modeled.
"""
READS = ()

ORDINALS = set(
    'first second third fourth fifth sixth seventh eighth ninth tenth eleventh '
    'twelfth thirteenth fourteenth fifteenth sixteenth seventeenth eighteenth '
    'nineteenth twentieth zeroth next last'.split()
)
LATE = set('tenth eleventh twelfth thirteenth fourteenth fifteenth sixteenth '
           'seventeenth eighteenth nineteenth twentieth'.split())
# Noun strength after an ordinal, 'next', and 'last'.
EVENTS = {
    'time': (3.8, 3.4, 2.45), 'year': (4.4, 3.6, 2.94),
    'season': (3.1, 2.5, 2.0), 'week': (3.8, 3.05, 1.97),
    'day': (2.1, 1.71, 1.13), 'night': (1.7, 1.6, 2.0),
    'month': (2.7, 2.6, 1.6), 'hour': (1.5, 1.5, 1.2),
    'minute': (1.0, 1.0, 1.75), 'weekend': (3.5, 2.5, 1.75),
    'generation': (2.5, 2.3, 1.5), 'edition': (2.3, 1.5, 1.0),
    'round': (1.0, 0.8, 0.75), 'semester': (2.7, 2.2, 1.8),
    'anniversary': (2.0, 1.0, 1.0), 'century': (0.9, 1.0, 0.75),
    'iteration': (1.8, 1.5, 1.0), 'quarter': (1.4, 1.2, 0.8),
    'version': (1.5, 1.0, 0.8), 'birthday': (1.3, 1.0, 0.8),
    'summer': (1.8, 2.0, 2.2), 'winter': (1.8, 2.4, 2.0),
}
TRANSITIONS = {
    'firstly': -1.4, 'secondly': -2.4, 'thirdly': -2.0,
    'finally': -0.2, 'furthermore': -0.45, 'moreover': -0.45,
    'additionally': -0.2, 'lastly': -1.0,
    '首先': -2.0, '其次': -2.4, '其次是': -2.8, '然后': -0.5,
    '此外': -0.9, 'まず': -2.0, 'まずは': -0.6,
}
INTRODUCTIONS = {
    'debut': 1.2, 'debuted': 0.75, 'inaugural': 1.2,
    'premiere': 0.55, 'beginning': 0.25, '首次': 1.45,
    '初めて': 1.0, '首': 0.55, '首个': 1.1,
}
FOREIGN_ORDINALS = {
    'erste': 1.1, 'ersten': 1.5, 'première': 0.7, 'primer': 0.55,
    'primera': 0.9, 'prima': 0.5, 'primeiro': 1.0, 'primeira': 1.0,
    'перв': 1.2, 'первый': 1.0, 'первого': 1.4, 'первой': 0.55,
    'втор': 0.8, 'pierws': 1.1,
}
STRUCTURAL = {
    'order': -0.6, 'element': -0.6, 'part': -0.6, 'point': -0.6,
    'place': -0.6, 'in': -0.45, 'with': -0.45, 'on': -0.45,
    'off': -2.0, 'up': -2.0, 'and': -0.2,
}
MODIFIERS = set('few two three four five six full consecutive straight'.split())
FIRST_ACTIONS = set('appeared described introduced published reported recorded '
                    'released discovered observed used invented'.split())
DAYS = set('monday tuesday wednesday thursday friday saturday sunday'.split())
NUMERALS = set('0123456789一二三四五六七八九十百千万两')


def event(noun, previous):
    column = 1 if previous == 'next' else 2 if previous == 'last' else 0
    strength = EVENTS[noun][column]
    if previous == 'first':
        strength *= 1.04 if noun == 'time' else 1.15
    elif previous == '#ordinal':
        strength *= 0.8 if noun == 'century' else 0.6
    elif previous in LATE:
        strength *= 0.65
    return strength


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev, earlier, capital, boundary = ('', '', False, False)
    if carry is not None and carry[0] == doc:
        prev, earlier, capital, boundary = carry[1:]
    raw = prefix.token_strings[-1]
    word = raw.strip().lower().lstrip('-._')
    cap = raw.strip()[:1].isupper()
    value = FOREIGN_ORDINALS.get(word, 0.0)
    if word in ORDINALS:
        value = {'first': 1.85, 'next': 0.88, 'last': 0.24}.get(word, 1.33)
        if word in {'fifth', 'sixth', 'seventh'}:
            value = 1.45
        if word in LATE:
            value = 1.05
        spaced = raw.startswith(' ')
        if word == 'last':
            value = (0.05 if cap else 0.23) if spaced else (-0.05 if cap else 0.03)
        elif word == 'next':
            value = 0.3 if cap else 0.88 if spaced else 0.52
        else:
            value -= 0.38 * (not raw.startswith((' ', '-')))
            value -= 0.22 * cap
    if prev and word and not raw[:1].isspace() and prev + word in ORDINALS:
        word, value = prev + word, 1.2
    value = TRANSITIONS.get(word, INTRODUCTIONS.get(word, value))
    if raw in {'st', 'nd', 'rd', 'th'} and prev[-1:].isdigit():
        value = 0.77 if word == 'st' else 1.1
        word = '#ordinal'
    ordered = prev in ORDINALS or prev == '#ordinal'
    noun = word[:-1] if word.endswith('s') else word
    if word.endswith('ies'):
        noun = word[:-3] + 'y'
    if noun in DAYS:
        noun = 'day'
    if noun in EVENTS:
        if ordered:
            value = event(noun, prev)
            if prev == 'next' and not boundary:
                value *= 0.6
        elif prev in MODIFIERS and earlier in ORDINALS:
            value = 0.4 * event(noun, earlier)
        elif prev in {'final', 'previous', 'inaugural', 'earliest'}:
            value = EVENTS[noun][2] * (0.65 if prev == 'previous' else 1.0)
        elif prev in {'each', 'every', 'one'}:
            value = 0.6 if noun in {'time', 'year', 'night'} else 0.3
    if prev == 'first' and word in FIRST_ACTIONS:
        value = 1.3
    if ordered:
        value = STRUCTURAL.get(word, value)
        if word == 'ly':
            value = -4.4 if prev == 'first' else -3.5
        elif word in {',', ':', ';'}:
            value = -1.3 if capital else -0.35
        elif word in {'thing', 'things'}:
            value = -1.15 if word == 'things' else -2.8
        elif word == 'of':
            value = -0.8
            if prev == 'first':
                value = -2.55 if capital else -1.3
        elif prev == 'first' and word in {'order', 'place'}:
            value = -1.0
        elif word == 'to' and prev == 'next':
            value = -0.47
        elif word in {'few', 'consecutive', 'straight'}:
            value = 1.4 if prev == 'first' else 0.7
        if prev == '#ordinal' and value < 0:
            value *= 0.35
    elif prev in TRANSITIONS and word in {',', '，'}:
        value = -1.2 if prev in {'firstly', 'secondly', 'thirdly'} else -0.5
    if word == 'foremost' and prev == 'and':
        value = -2.4
    if word in {'ever', 'hand'} and prev == 'first':
        value = 2.8 if word == 'ever' else 1.6
    if word in {'fois', 'vez', 'volta'} and prev in FOREIGN_ORDINALS:
        value = {'fois': 2.8, 'vez': 3.5, 'volta': 1.6}[word]
    chinese = word.lstrip('的')
    if chinese.startswith('第'):
        value = 1.3 if chinese.startswith('第一') else 1.1
        if chinese.startswith(('第二', '第三')):
            value = 0.8
        if chinese.endswith('次'):
            value += 0.7
    elif '第' in prev and word and all(c in NUMERALS for c in word):
        word, value = prev + word, 0.3
    elif '第' in prev and word in {'代', '季', '赛季', '次', '届', '季度'}:
        value = 3.2 if word in {'代', '季', '赛季'} else 1.7
    return (doc, word, prev, cap, raw.startswith(' ')), float(value)

