"""Layer-0 MLP component 2939: an ordinal-sequence detector.

It fires on words that count occurrences in order: "first", "second", "third",
"next", the ordinal suffix in "25th", and the Chinese 第/代 ordinal markers. It
fires harder on the time or repetition noun right after one ("first time",
"second year", "next season"). Sequencing phrases built on an ordinal ("Firstly",
"first thing", "first of all") push it negative.
"""

READS = ()

ORDINALS = {
    "first": 1.8, "second": 1.3, "third": 1.3, "fourth": 1.2, "fifth": 1.5,
    "sixth": 1.5, "next": 0.8,
}
# words that count as a sequence marker before a time noun
MARKERS = set(ORDINALS) | {"last", "final"}
UNITS = {
    "time", "times", "year", "years", "season", "week", "edition", "generation",
    "century", "night", "day", "month", "round", "anniversary", "debut", "premiere",
}
# words that continue a sequencing phrase after an ordinal
SEQUENCE_TAILS = {"ly", "thing", "of", "foremost", "order", "-order", "place"}


def word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    s = prefix.token_strings
    w = word(s[-1])
    prev = word(s[-2]) if len(s) > 1 else ""
    if w in ORDINALS:
        return None, ORDINALS[w]
    if w in ("st", "nd", "rd", "th") and prev[-1:].isdigit():
        return None, 0.8
    if "第" in s[-1] or w == "代":
        return None, 1.2
    if w in UNITS and prev in MARKERS:
        return None, 2.5
    if prev in ORDINALS and w in SEQUENCE_TAILS:
        return None, -2.5
    if prev in ORDINALS and w == ",":
        return None, -0.9
    return None, 0.0

