        value = 1.0
        ordinal_left = 4
    elif token.startswith("第") and any(char.isdigit() for char in token):
        value = 1.0
    elif ordinal_left and token.isdigit():
        value = 0.35
        ordinal_left -= 1
    elif ordinal_left and token in CHINESE_UNITS:
        value = 0.75
        ordinal_left = 0
    elif ordinal_left:
        ordinal_left -= 1
    elif token.startswith(CHINESE_PREFIXES):
        value = 1.5
    elif token.startswith(RUSSIAN_ROOTS):
        value = 0.8
    elif previous.startswith("перв") and token in RUSSIAN_ENDINGS:
        value = 0.45
    elif token in OTHER_ORDINALS:
        value = 1.0
    elif token.startswith(GERMAN_ROOTS + FRENCH_ROOTS + SPANISH_ROOTS):
        value = 1.0
    elif token == "まずは":
        value = -0.6

    # A few calendar terms respond in date-like or sequence-like phrases.
    if token == "day" and previous in {"one", "last", "next"}:
        value = 0.35
    if token == "year" and previous in {"every", "last", "next"}:
        value = 0.6
    if token in MONTHS and previous in SUFFIX_VALUES:
        value = 0.5

    new_carry = (doc, token, ordinal_left)
    return new_carry, float(value)

programs.sol:
"""Short horizontal spacer runs, especially indentation, give negative activation.

Run length means characters in the current token, not total indentation. The
length response peaks at five to nine spaces and is not monotone. Line breaks
make very short runs more negative; code-line endings and literal backslash-n
text modulate common four-space indentation fragments. Tabs, nonbreaking
spaces, blank lines, and decorative rules are related cases. Ordinary text
receives zero. Constants summarize training measurements, without token ids.
"""
from math import exp

READS = ()
SPACE_RESPONSE = {
    4: -1.42, 5: -2.76, 6: -3.18, 7: -2.30,
    8: -2.13, 9: -2.83, 10: -2.15, 11: -1.30,
    12: -0.98, 13: -1.27, 14: -0.85, 15: -0.48,
    16: -0.49, 17: -0.64, 18: -0.58, 19: -0.18, 20: -0.13,
}
TAB_THEN_SPACES = {
    2: -0.30, 3: 0.08, 4: -0.78, 5: -1.86,
    7: -1.07, 8: -0.49, 9: -0.98, 11: -0.10, 13: -0.29,
}
BLANK_LINE_RESPONSE = {
    3: -0.16, 4: -0.37, 5: -1.00, 6: -1.64,
    7: -1.54, 8: -1.02, 9: -1.33, 10: -1.65,
    11: -1.00, 12: -0.58, 13: -0.40, 15: -0.52,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = "" if first else carry[1]
    token = prefix.token_strings[-1]
    newline = previous.endswith(("\n", "\r"))
    line_end = previous.rstrip("\r\n")[-1:]
    boundary = newline and line_end in (";", "{", "}")
    colon = newline and line_end == ":"
    escaped_break = False if first else carry[2]
    value = 0.0

    if token and not token.strip(" "):
        n = len(token)
        if n == 1:
            value = -0.73 if newline else 0.0
        elif n == 2:
            value = -0.77 if newline else -0.26
        elif n == 3:
            value = (-0.38 if newline else 0.09)
            value += 0.13 * boundary - 0.06 * colon + 0.08 * escaped_break
        else:
            value = SPACE_RESPONSE.get(n, 0.0 if n > 20 else -0.15)
            if n == 4:
                value = -1.50 if newline else -1.25
            elif n == 7:
                value += 0.42 * newline + 0.30 * boundary
                value += -0.20 * colon + 0.38 * escaped_break
            elif n == 11:
                value += 0.30 * newline + 0.24 * boundary
                value += -0.15 * colon + 0.39 * escaped_break
            elif n == 15:
                value += -0.04 * newline + 0.12 * boundary
                value += -0.09 * colon + 0.20 * escaped_break
            if first:
                value *= 0.65
    elif token and not token.strip("\t"):
        n = len(token)
        if n == 1:
            value = -0.22 if newline else 0.12
        elif n == 2:
            value = -0.59
        elif n == 3:
            value = -0.37 if newline else -0.12
        elif n == 4:
            value = -0.26 if newline else 0.10
        else:
            value = min(0.25, -0.08 + 0.11 * (n - 5))
    elif token.startswith("\t") and not token[1:].strip(" "):
        n = len(token) - 1
        value = TAB_THEN_SPACES.get(n, 0.0)
        if n >= 15:
            value = min(0.6, 0.06 + 0.04 * (n - 15))
    elif token.isspace() and not token.strip(" \r\n"):
        n = max(len(part.strip("\r")) for part in token.split("\n"))
        value = BLANK_LINE_RESPONSE.get(n, -0.15 if n >= 14 else 0.0)
        if token.startswith("\n"):
            value *= 0.8
    elif token and not token.strip(" \u00a0"):
        n = token.count("\u00a0")
        if " " in token and n >= 2:
            value = -1.25
        else:
            value = {3: 0.16, 4: -1.07, 7: -1.24, 8: -0.72}.get(n, 0.0)
    else:
        rule = token.strip(" \r\n")
        if len(rule) >= 3 and len(set(rule)) == 1:
            scale = {"-": 1.0, "=": 0.8, ".": 0.55,
                     "_": 0.5, "~": 0.7}.get(rule[0], 0.0)
            n = len(rule)
            strength = 1.95 * exp(-((n - 7.4) / 4.4) ** 2)
            if n <= 4:
                strength = 0.13 if n == 3 else 0.4
            if "\n" in token:
                strength *= 0.6
            value = -scale * strength
    # A literal backslash-n can occupy either one token or two.
    escaped = token.endswith("\\n") or (token == "n" and previous.endswith("\\"))
    return (doc, token, escaped), float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 2940: an indentation detector.

It goes strongly negative on the whitespace-only token that sets the indentation of a
line of code, i.e. a run of about 4 to 10 spaces (the deepest values are at 5-6 and 9-10
spaces). Wider runs (11-16 spaces) are moderately negative, and tab indents and
ordinary text are near zero. A bare space or a bare newline also stays near zero, and
a 1-3 space run is only slightly negative when it follows a newline.

The program keeps no state: it reads only the newest token and the one before it.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    # Only whitespace tokens (spaces, tabs, newlines, no-break spaces) can fire.
    if not token or token.strip(" \t\xa0\n") != "":
        return carry, 0.0
    after_newline = prefix.position > 0 and "\n" in prefix.token_strings[-2]
    spaces = len(token.rstrip("\n").replace("\t", ""))
    if "\t" in token:
        # Tab indents: mostly silent; a tab followed by a 4-8 space run is negative.
        value = -1.2 if 4 <= spaces <= 8 else -0.4 if token.count("\t") >= 2 and spaces == 0 else 0.0
    elif spaces == 0:
        value = 0.0
    elif spaces <= 3:
        # Short runs: negative mostly when they start a line.
        if after_newline:
            value = -0.7 if spaces == 1 else -0.75 if spaces == 2 else -0.3
        else:
            value = 0.0 if spaces == 1 else -0.2 if spaces == 2 else 0.1
    elif spaces == 4:
        value = -1.3
    elif spaces <= 10:
        value = -2.3  # code indentation, the strongest band
    elif spaces <= 14:
        value = -0.9
    elif spaces <= 16:
        value = -0.45
    else:
        value = -0.2
    return carry, float(value)

programs.luna:
"""Approximate a formatting-whitespace response.

Ordinary tokens get zero. Horizontal runs of spaces and some tabbed runs
get negative scores, with the value determined by the run's width.
"""
READS = ()


def space_run_score(width):
    if width == 1:
        return -0.15
    if width == 2:
        return -0.75
    if width == 3:
        return -0.30
    if width == 4:
        return -1.35
    if width in (5, 6):
        return -2.20
    if width in (7, 8):
        return -1.80
    if width in (9, 10):
        return -2.75
    if width in (11, 12):
        return -1.00
    if 13 <= width <= 16:
        return -0.60
    if width >= 30:
        return -0.25
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[prefix.position]
    value = 0.0
    if token and token.isspace() and "\n" not in token:
        if "\t" not in token:
            value = space_run_score(len(token))
        elif token.count(" ") >= 5:
            value = -1.0
        elif token.count("\t") >= 2:
            value = -0.50
        elif token == "\t":
            value = -0.15
    return None, value

"""A small numeral-dependent bias, strongest for 8 and 9."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    if token in ("8", "9"):
        return None, 0.13
    if len(token) == 1 and token in "01234567":
        return None, -0.15
    return None, 0.0

programs.sol:
"""Approximate prominent software/web responses, plus percentage marks.

Use named technologies, errors, package/interface names and resource routes.
Affixes distinguish qualified names from prose and source-file extensions.
Weak spelling-shape fallbacks cover other identifiers. Keep a short identifier
tail to join split names and the previous token for numeric percentages;
reset state at document boundaries. Structural markers and source-tree words
have separate values. Unrelated lexical exceptions are deliberately omitted.
"""
import re

READS = ()
TECH_NAMES = {
    'java': 1.20, 'javax': 1.10, 'python': 0.70, 'php': 0.60,
    'ruby': 0.50, 'perl': 0.52, 'golang': 1.03, 'javascript': 0.50,
    'typescript': 0.36, 'matlab': 0.41, 'sql': 0.32, 'bash': 0.21,
    'linux': 0.53, 'android': 0.58, 'androidx': 0.80,
}
DEVELOPER_TOOLS = set('git github grep npm docker sudo terraform'.split())
SOFTWARE_NAMES = set('django laravel kubernetes graphql rewire illuminate '
                 'pygame matplotlib glfw gnu shutil'.split())
PACKAGES = set('apache springframework eclipse jetty servlet awt nio '
               'firebase vaadin minecraft maven'.split())
BRANDS = set('google amazon aws wikipedia facebook instagram twitter microsoft'.split())
ROUTES = {'wiki': 1.60, 'repos': 1.50, 'problems': 1.70,
          'repository': 0.73, 'examples': 0.60, 'docs': 0.42}
INTERFACES = set('web http auth services ui os permission annotation view '
                 'widget app net util lang security'.split())
EXTENSIONS = {
    'java': 0.91, 'php': 0.29, 'json': 0.32, 'jar': 0.27,
    'yaml': 0.20, 'h': -0.14, 'ts': -0.09, 'go': -0.06,
    'rs': -0.05, 'py': 0.07, 'md': 0.08, 'js': 0.05,
}
MARKS = {
    '</tool_response>': 0.31, '<tool_response>': -0.24,
    '</think>': 0.23, '<think>': 0.12, '</tool_call>': 0.10,
    '{%': 0.36, '[]': 0.24, '([]': 0.41, '#': 0.07, '://': 0.11,
}


def response(raw, previous, tail):
    token = raw.strip()
    word = token.lstrip('._/-(@\\').lower()
    joined = (tail + token).lower() if token[:1].isalpha() else word
    if joined in TECH_NAMES or joined in SOFTWARE_NAMES:
        word = joined
    if token == '%':
        return 0.56 if raw == '%' and previous[-1:].isdigit() else 0.23
    if token in {'%)', '%,', '%.'}:
        return 0.23
    if token in MARKS:
        return MARKS[token]
    if not word:
        return 0.0
    if token.startswith('.') and word in EXTENSIONS:
        return EXTENSIONS[word]
    if word in TECH_NAMES:
        return TECH_NAMES[word] + (0.25 if token.startswith('/') else 0.0)
    if word in DEVELOPER_TOOLS or word in SOFTWARE_NAMES:
        return 0.62 + (0.15 if token.startswith('.') else 0.0)
    if word in {'error', 'errors', 'perror'}:
        return 0.66 if word == 'errors' else 0.80
    if token.endswith('Error'):
        return 0.98
    if word == 'err':
        return 0.36
    if word == 'config':
        return 0.49
    if word in PACKAGES:
        return 1.65 if word == 'apache' and token[:1] in './' else 0.78
    if word in BRANDS:
        return 0.75 if token[:1] in './' else 0.27
    if word == 'www':
        return 1.41 if previous.endswith('://') else 0.85
    if word in {'website', 'web', 'internet', 'percent'} and not token.startswith('.'):
        return 0.22
    if word in {'src', 'ignore', 'workspace'}:
        if token.startswith('/'):
            return 0.12 if word == 'workspace' else -0.09
        return -0.20
    if token.startswith('.'):
        if word in {'com', 'org', 'io'}:
            return 0.80 if word == 'io' else 0.32
        if word in INTERFACES:
            return 0.65
        return 0.28 if re.search('[a-z][A-Z]', token) else 0.04
    if token.startswith('/') and word[:1].isalpha():
        if word in ROUTES:
            return ROUTES[word]
        return 0.52 if word in {'node', 'bin'} else 0.05
    if token.startswith('_') and word[:1].isalpha():
        if word in {'modules', 'html'}:
            return 0.21
        return -0.10 if word == 'test' else 0.07
    if token in {'-plugin', '-cli', '-sdk', '-dev', '-eslint'}:
        return 0.70
    return 0.16 if re.search('[a-z][A-Z]', token) else 0.0


def step(carry, prefix, upstream):
    doc, raw = prefix.document_ids[-1], prefix.token_strings[-1]
    previous, tail = carry[1:] if carry is not None and carry[0] == doc else ('', '')
    value = response(raw, previous, tail)
    match = re.search('[A-Za-z0-9_]+$', tail + raw)
    tail = match.group()[-40:] if match else ''
    return (doc, raw, tail), float(value)

programs.luna:
"""Mostly predict the usual small activation, with a modest text-form adjustment."""

READS = ()


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1].strip()
    bump = 0.0
    if s == "%":
        bump = 0.07
    elif any(c in s for c in "/._-@{}") and any(c.isalnum() for c in s):
        bump = 0.05
    elif any(c.isupper() for c in s):
        bump = 0.024
    return None, 0.00551 + bump

programs.sol:
"""Mostly a negative detector for the spelling 'arch' and archival words.

Bare arch is strongest; March, architecture and other arch-word families
are weaker. Related Chinese arch/archive words also respond. A secondary
positive response covers essential/effective and minimal/little words.
One previous token suffices for split endings and adjacent 'of'/'to'.
Unrecognized text is silent, and document boundaries clear the context.
"""
READS = ()

ARCH_TRANSLATIONS = {
    '拱': -4.4, '弓': -2.3,
    '档': -4.5, '檔': -3.0,
    '档案': -3.5, '檔案': -1.25,
    '架构': -1.1, '文档': -0.75,
}
POSITIVE_WORDS = {
    'essential': 1.0, 'essentially': 1.7,
    'effectively': 0.7, 'little': 0.7,
    'minimal': 0.49, 'minimum': 0.24, 'necessary': 0.35,
}


def response(text):
    clean = text.strip()
    word = clean.lstrip('_/.').lower()
    if word == 'arch':
        if clean.startswith(('_', '/')):
            return -5.3
        return -6.9 if text[0].isspace() and clean.islower() else -6.3
    if word.startswith('archiv'):
        if word.endswith(('o', 'os')):  # Spanish archivo(s).
            return -1.5
        return -4.2 if clean[0].isupper() else -3.7
    if word.startswith('architect'):
        return -1.05 if word.endswith(('ural', 'ures')) else -1.5
    if word.startswith('archbishop'):
        return -3.1
    if 'hierarch' in word:
        return -0.6
    if word.startswith(('archae', 'archer', 'archie', 'starch', 'patriarch', 'anarch')):
        return -2.2
    if word.startswith(('march', 'monarch', 'parch')):
        return -0.45 if 'é' in word else -1.5
    if word == 'archy':
        return -2.7
    if word in ('arc', 'arcs', 'orch'):
        return -0.75
    if word in ('rch', 'earch', 'torch', 'archical', 'arthritis'):
        return -1.3
    if word == 'ess':
        return 0.7 if text[0].isspace() or clean[0].isupper() else 0.2
    if word in POSITIVE_WORDS:
        value = POSITIVE_WORDS[word]
        return value * (0.5 if clean[0].isupper() else 1.0)
    return ARCH_TRANSLATIONS.get(clean, 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    text = prefix.token_strings[-1]
    word = text.strip().lower()
    before = previous.strip().lstrip('_/.').lower()
    value = response(text)
    if before == 'arch' and text and text[0].isalpha():
        if word.startswith(('ives', 'iving', 'ived')):
            value = -4.0
        elif word in ('es', 'ing', 'ae'):
            value = -3.1
        elif word.startswith(('iv', 'ite', 'bishop', 'ery')):
            value = -1.8
        elif word.startswith('ipel'):
            value = -0.15
        else:
            value = -0.6
    if word == 'arch' and not text[0].isspace():
        if before.endswith('hier'):
            value = -2.8
        elif before.endswith(('patri', 'matri', 'atri')):
            value = -4.5
    if word == 'of' and 'arch' in before and 'search' not in before:
        value = max(-2.2, 0.5 * response(previous))
    if word == 'to' and before in ('essential', 'necessary', 'little'):
        value = 0.48 if before == 'essential' else 0.34
    return (doc, text), float(value)

programs.luna:
"""Spot a rare orthographic feature: arch- words and related endings."""
READS = ()

def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].casefold().strip()
    if word == 'arch':
        return None, -7.0
    if word.startswith(('arch', 'march')):
        return None, -1.5
    if word.endswith(('archy', 'archical')):
        return None, -0.6
    return None, 0.0
